CONTENTS = {'app/routes/admin.py': 'from __future__ import annotations\nfrom app.services.search_providers import serper_status\n\nfrom pathlib import Path\nfrom urllib.parse import urlencode\n\nfrom fastapi import APIRouter, Request\nfrom fastapi.responses import FileResponse, HTMLResponse, RedirectResponse, Response\nfrom sqlalchemy import func, or_, select\nfrom sqlalchemy.exc import IntegrityError\nfrom sqlalchemy.orm import selectinload\n\nfrom ..config import settings\nfrom ..database import SessionLocal\nfrom ..models import AdminUser, Disaster, DiscoveryCandidate, MissingPerson, Source, Submission\nfrom ..security import verify_password\nfrom ..services.discovery import discover_candidates, generate_queries, google_search_url\nfrom ..services.wide_discovery import collect_known_source_scopes, generate_wide_queries, run_wide_discovery\nfrom ..services.search_providers import SearchProviderUnavailable, brave_status\nfrom ..services.candidate_extract import extract_candidate_prefill\nfrom ..services.ai_review import build_free_ai_review_prompt, parse_free_ai_review\nfrom ..services.master_records import apply_submission_to_master\nfrom ..services.duplicates import find_duplicates\nfrom ..services.exports import build_csv, build_xlsx\nfrom ..services.files import save_image\nfrom ..services.source_images import discover_public_post_image, download_public_source_image, is_allowed_public_image_url\nfrom ..services.source_ocr import extract_ocr_text, ocr_available\nfrom ..services.normalization import affected_location_match, canonicalize_url, detect_platform\nfrom ..services.share_cards import build_share_card\nfrom .common import admin_gate, audit, next_case_number, parse_date, parse_int, parse_time, render\n\nrouter = APIRouter()\n\n\ndef _normalize_gender(value) -> str | None:\n    folded = str(value or "").strip().casefold()\n    if folded in {"male", "m", "पुरुष"}:\n        return "Male"\n    if folded in {"female", "f", "महिला"}:\n        return "Female"\n    return None\n\n\n@router.get("/admin/media/{filename}")\ndef admin_media(request: Request, filename: str):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    if Path(filename).name != filename:\n        return HTMLResponse("Not found", status_code=404)\n    with SessionLocal() as db:\n        referenced = db.scalar(\n            select(func.count()).select_from(Submission).where(Submission.photo_path == filename)\n        ) or db.scalar(\n            select(func.count()).select_from(MissingPerson).where(MissingPerson.photo_path == filename)\n        )\n        if not referenced:\n            return HTMLResponse("Not found", status_code=404)\n    path = settings.upload_dir / filename\n    if not path.is_file():\n        return HTMLResponse("Not found", status_code=404)\n    return FileResponse(path)\n\n\n@router.get("/admin/login", response_class=HTMLResponse)\ndef login_page(request: Request):\n    return render(request, "admin_login.html", error=None)\n\n\n@router.post("/admin/login", response_class=HTMLResponse)\nasync def login(request: Request):\n    form = await request.form()\n    username = str(form.get("username") or "")\n    password = str(form.get("password") or "")\n    with SessionLocal() as db:\n        admin = db.scalar(select(AdminUser).where(AdminUser.username == username, AdminUser.active.is_(True)))\n        if admin is None or not verify_password(password, admin.password_hash):\n            return render(request, "admin_login.html", error="Invalid credentials")\n        request.session["admin"] = admin.username\n        audit(db, request, "login", "admin", admin.id)\n        db.commit()\n    return RedirectResponse("/admin", status_code=303)\n\n\n@router.post("/admin/logout")\ndef logout(request: Request):\n    request.session.clear()\n    return RedirectResponse("/admin/login", status_code=303)\n\n\n@router.get("/admin", response_class=HTMLResponse)\ndef admin_dashboard(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        stats = {\n            "people": db.scalar(select(func.count(MissingPerson.id)).where(MissingPerson.archived.is_(False))) or 0,\n            "published": db.scalar(\n                select(func.count(MissingPerson.id)).where(\n                    MissingPerson.published.is_(True), MissingPerson.archived.is_(False)\n                )\n            )\n            or 0,\n            "pending": db.scalar(select(func.count(Submission.id)).where(Submission.status == "pending")) or 0,\n            "candidates": db.scalar(\n                select(func.count(DiscoveryCandidate.id)).where(DiscoveryCandidate.status == "new")\n            )\n            or 0,\n            "sources": db.scalar(select(func.count(Source.id))) or 0,\n        }\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        return render(request, "admin_dashboard.html", stats=stats, disasters=disasters)\n\n\n@router.get("/admin/events", response_class=HTMLResponse)\ndef admin_events(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        return render(request, "admin_events.html", disasters=disasters, error=None)\n\n\n@router.post("/admin/events")\nasync def admin_event_create(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    code = str(form.get("code") or "").strip().upper()\n    name = str(form.get("name") or "").strip()\n    start_date = parse_date(form.get("start_date"))\n    if not code or not name or not start_date:\n        return RedirectResponse("/admin/events", status_code=303)\n    with SessionLocal() as db:\n        disaster = Disaster(\n            code=code,\n            name=name,\n            disaster_type=str(form.get("disaster_type") or "flood").strip(),\n            start_date=start_date,\n            affected_locations=str(form.get("affected_locations") or "").strip(),\n            active=True,\n        )\n        db.add(disaster)\n        try:\n            db.flush()\n            audit(db, request, "create_event", "disaster", disaster.id, name)\n            db.commit()\n        except IntegrityError:\n            db.rollback()\n    return RedirectResponse("/admin/events", status_code=303)\n\n\n@router.post("/admin/events/{disaster_id}/update")\nasync def admin_event_update(request: Request, disaster_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    with SessionLocal() as db:\n        disaster = db.get(Disaster, disaster_id)\n        if disaster is None:\n            return HTMLResponse("Not found", status_code=404)\n        disaster.name = str(form.get("name") or disaster.name).strip()\n        disaster.disaster_type = str(form.get("disaster_type") or disaster.disaster_type).strip()\n        disaster.affected_locations = str(form.get("affected_locations") or "").strip()\n        disaster.active = str(form.get("active") or "") == "on"\n        audit(db, request, "update_event", "disaster", disaster.id, disaster.name)\n        db.commit()\n    return RedirectResponse("/admin/events", status_code=303)\n\n\n@router.get("/admin/people", response_class=HTMLResponse)\ndef admin_people(request: Request, disaster_id: int | None = None, q: str = ""):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        stmt = (\n            select(MissingPerson)\n            .options(selectinload(MissingPerson.sources))\n            .order_by(MissingPerson.created_at.desc())\n        )\n        if disaster_id:\n            stmt = stmt.where(MissingPerson.disaster_id == disaster_id)\n        if q.strip():\n            pattern = f"%{q.strip()}%"\n            stmt = stmt.where(\n                or_(\n                    MissingPerson.name.ilike(pattern),\n                    MissingPerson.name_ne.ilike(pattern),\n                    MissingPerson.case_number.ilike(pattern),\n                )\n            )\n        people = list(db.scalars(stmt.limit(500)).all())\n        return render(\n            request,\n            "admin_people.html",\n            people=people,\n            disasters=disasters,\n            selected_disaster=disaster_id,\n            q=q,\n        )\n\n\n@router.get("/admin/people/{person_id}", response_class=HTMLResponse)\ndef admin_person(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.scalar(\n            select(MissingPerson)\n            .options(selectinload(MissingPerson.sources))\n            .where(MissingPerson.id == person_id)\n        )\n        if person is None:\n            return HTMLResponse("Not found", status_code=404)\n        merge_targets = list(\n            db.scalars(\n                select(MissingPerson).where(\n                    MissingPerson.disaster_id == person.disaster_id,\n                    MissingPerson.id != person.id,\n                    MissingPerson.archived.is_(False),\n                ).order_by(MissingPerson.name)\n            ).all()\n        )\n        return render(\n            request,\n            "admin_person.html",\n            person=person,\n            error=None,\n            public_url=f"{settings.public_base_url}/person/{person.case_number}",\n            merge_targets=merge_targets,\n        )\n\n\n@router.post("/admin/people/{person_id}/edit")\nasync def admin_person_edit(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person is None:\n            return HTMLResponse("Not found", status_code=404)\n        person.name = str(form.get("name") or person.name).strip()\n        person.name_ne = str(form.get("name_ne") or "").strip() or None\n        person.age = parse_int(form.get("age"))\n        person.gender = _normalize_gender(form.get("gender"))\n        person.last_seen_date = parse_date(form.get("last_seen_date"))\n        person.last_seen_time = parse_time(form.get("last_seen_time"))\n        person.last_seen_location = str(form.get("last_seen_location") or "").strip()\n        person.clothing = str(form.get("clothing") or "").strip() or None\n        person.identification_details = str(form.get("identification_details") or "").strip() or None\n        person.public_contact_number = str(form.get("public_contact_number") or "").strip() or None\n        person.residential_address_private = str(form.get("residential_address_private") or "").strip() or None\n        audit(db, request, "edit_person", "person", person.id)\n        db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/publish")\ndef admin_publish(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person:\n            person.published = not person.published\n            audit(db, request, "publish_toggle", "person", person.id, str(person.published))\n            db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/archive")\ndef admin_archive(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person:\n            person.archived = True\n            person.published = False\n            audit(db, request, "archive_person", "person", person.id)\n            db.commit()\n    return RedirectResponse("/admin/people", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/merge")\nasync def admin_merge_person(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    target_id = parse_int(form.get("target_person_id"))\n    if not target_id or target_id == person_id:\n        return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n    with SessionLocal() as db:\n        source = db.scalar(\n            select(MissingPerson).options(selectinload(MissingPerson.sources)).where(MissingPerson.id == person_id)\n        )\n        target = db.scalar(\n            select(MissingPerson).options(selectinload(MissingPerson.sources)).where(MissingPerson.id == target_id)\n        )\n        if source is None or target is None or source.disaster_id != target.disaster_id:\n            return HTMLResponse("Invalid merge target", status_code=400)\n\n        target_urls = {item.url for item in target.sources}\n        for source_item in list(source.sources):\n            if source_item.url in target_urls:\n                db.delete(source_item)\n            else:\n                source_item.person_id = target.id\n                target_urls.add(source_item.url)\n\n        db.execute(\n            Submission.__table__.update()\n            .where(Submission.person_id == source.id)\n            .values(person_id=target.id)\n        )\n\n        # Fill only blank canonical fields. The target remains the admin-selected master record.\n        for field in [\n            "name_ne", "age", "gender", "photo_path", "residential_address_private",\n            "last_seen_date", "last_seen_time", "clothing", "identification_details",\n            "public_contact_number", "private_contact_number",\n        ]:\n            if getattr(target, field) in (None, "") and getattr(source, field) not in (None, ""):\n                setattr(target, field, getattr(source, field))\n        if not target.last_seen_location and source.last_seen_location:\n            target.last_seen_location = source.last_seen_location\n\n        source.archived = True\n        source.published = False\n        audit(\n            db,\n            request,\n            "merge_duplicate_person",\n            "person",\n            source.id,\n            f"merged_into={target.id}; target_case={target.case_number}",\n        )\n        db.commit()\n    return RedirectResponse(f"/admin/people/{target_id}", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/source")\nasync def admin_add_source(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    url = canonicalize_url(str(form.get("url") or ""))\n    if not url:\n        return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n    with SessionLocal() as db:\n        if db.get(MissingPerson, person_id) is None:\n            return HTMLResponse("Not found", status_code=404)\n        existing = db.scalar(select(Source).where(Source.person_id == person_id, Source.url == url))\n        if existing is None:\n            source = Source(\n                person_id=person_id,\n                platform=str(form.get("platform") or "facebook").strip(),\n                url=url,\n                source_name=str(form.get("source_name") or "").strip() or None,\n                source_text=str(form.get("source_text") or "").strip() or None,\n            )\n            db.add(source)\n            db.flush()\n            audit(db, request, "add_source", "source", source.id, url)\n            db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n@router.get("/admin/submissions", response_class=HTMLResponse)\ndef admin_submissions(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        submissions = list(\n            db.scalars(\n                select(Submission).where(Submission.status == "pending").order_by(Submission.created_at.desc())\n            ).all()\n        )\n        duplicate_map: dict[int, list[tuple[MissingPerson, float]]] = {}\n        location_match_map: dict[int, bool] = {}\n        disasters_by_id = {d.id: d for d in db.scalars(select(Disaster)).all()}\n        for sub in submissions:\n            disaster = disasters_by_id.get(sub.disaster_id)\n            location_match_map[sub.id] = bool(\n                disaster and affected_location_match(sub.last_seen_location, disaster.affected_locations)\n            )\n            if sub.kind == "missing_report" and sub.name:\n                duplicate_map[sub.id] = find_duplicates(\n                    db,\n                    disaster_id=sub.disaster_id,\n                    name=sub.name,\n                    location=sub.last_seen_location,\n                    age=sub.age,\n                    phone=sub.public_contact_number,\n                )\n        people = list(\n            db.scalars(\n                select(MissingPerson).where(MissingPerson.archived.is_(False)).order_by(MissingPerson.name)\n            ).all()\n        )\n        people_by_disaster: dict[int, list[MissingPerson]] = {}\n        for person in people:\n            people_by_disaster.setdefault(person.disaster_id, []).append(person)\n        return render(\n            request,\n            "admin_submissions.html",\n            submissions=submissions,\n            duplicate_map=duplicate_map,\n            location_match_map=location_match_map,\n            people_by_disaster=people_by_disaster,\n        )\n\n\n@router.post("/admin/submissions/{submission_id}/approve-new")\ndef approve_submission_new(request: Request, submission_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        sub = db.get(Submission, submission_id)\n        if sub is None or sub.status != "pending" or not sub.name:\n            return RedirectResponse("/admin/submissions", status_code=303)\n        disaster = db.get(Disaster, sub.disaster_id)\n        if disaster is None:\n            return RedirectResponse("/admin/submissions", status_code=303)\n        person = MissingPerson(\n            case_number=next_case_number(db, disaster),\n            disaster_id=sub.disaster_id,\n            name=sub.name,\n            name_ne=sub.name_ne,\n            age=sub.age,\n            gender=sub.gender,\n            photo_path=sub.photo_path,\n            residential_address_private=sub.residential_address_private,\n            last_seen_date=sub.last_seen_date,\n            last_seen_time=sub.last_seen_time,\n            last_seen_location=sub.last_seen_location or "Unknown",\n            clothing=sub.clothing,\n            identification_details=sub.identification_details,\n            public_contact_number=sub.public_contact_number,\n            private_contact_number=sub.reporter_phone_private,\n            published=False,\n        )\n        db.add(person)\n        db.flush()\n        sub.person_id = person.id\n        sub.status = "approved"\n        if sub.social_url:\n            db.add(\n                Source(\n                    person_id=person.id,\n                    platform=detect_platform(sub.social_url),\n                    url=sub.social_url,\n                    source_text=sub.notes,\n                )\n            )\n        audit(db, request, "approve_submission_new", "person", person.id, f"submission={sub.id}")\n        db.commit()\n        return RedirectResponse(f"/admin/people/{person.id}", status_code=303)\n\n\n@router.post("/admin/submissions/{submission_id}/attach")\nasync def attach_submission(request: Request, submission_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    person_id = parse_int(form.get("person_id"))\n    with SessionLocal() as db:\n        sub = db.get(Submission, submission_id)\n        person = db.get(MissingPerson, person_id) if person_id else None\n        if sub is None or person is None:\n            return RedirectResponse("/admin/submissions", status_code=303)\n        if person.disaster_id != sub.disaster_id:\n            return HTMLResponse("Cannot attach a submission to a person from a different disaster", status_code=400)\n        if sub.status != "pending":\n            return RedirectResponse("/admin/submissions", status_code=303)\n\n        updated_fields = apply_submission_to_master(\n            person,\n            sub,\n        )\n\n        if sub.social_url:\n            existing = db.scalar(select(Source).where(Source.person_id == person.id, Source.url == sub.social_url))\n            if existing is None:\n                db.add(\n                    Source(\n                        person_id=person.id,\n                        platform=detect_platform(sub.social_url),\n                        url=sub.social_url,\n                        source_text=sub.notes,\n                    )\n                )\n        sub.person_id = person.id\n        sub.status = "attached"\n        audit(\n            db,\n            request,\n            "attach_submission",\n            "person",\n            person.id,\n            (\n                f"submission={sub.id}; "\n                f"master_fields_updated={\',\'.join(updated_fields) or \'none\'}"\n            ),\n        )\n        db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n\n@router.post(\n    "/admin/submissions/{submission_id}/edit"\n)\nasync def edit_pending_submission(\n    request: Request,\n    submission_id: int,\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    form = await request.form()\n\n    with SessionLocal() as db:\n        sub = db.get(\n            Submission,\n            submission_id,\n        )\n\n        if (\n            sub is None\n            or sub.status != "pending"\n        ):\n            return RedirectResponse(\n                "/admin/submissions",\n                status_code=303,\n            )\n\n        name = str(\n            form.get("name")\n            or ""\n        ).strip()\n\n        if (\n            sub.kind == "missing_report"\n            and not name\n        ):\n            return HTMLResponse(\n                "Name is required",\n                status_code=400,\n            )\n\n        sub.name = name or sub.name\n\n        sub.name_ne = (\n            str(\n                form.get("name_ne")\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.age = parse_int(\n            form.get("age")\n        )\n\n        sub.gender = _normalize_gender(form.get("gender"))\n\n        sub.last_seen_date = parse_date(\n            form.get("last_seen_date")\n        )\n\n        sub.last_seen_time = parse_time(\n            form.get("last_seen_time")\n        )\n\n        sub.last_seen_location = (\n            str(\n                form.get(\n                    "last_seen_location"\n                )\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.clothing = (\n            str(\n                form.get("clothing")\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.identification_details = (\n            str(\n                form.get(\n                    "identification_details"\n                )\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.public_contact_number = (\n            str(\n                form.get(\n                    "public_contact_number"\n                )\n                or ""\n            ).strip()\n            or None\n        )\n\n        photo_upload = form.get(\n            "photo"\n        )\n\n        if (\n            photo_upload is not None\n            and getattr(\n                photo_upload,\n                "filename",\n                "",\n            )\n        ):\n            try:\n                photo_path = await save_image(\n                    photo_upload,\n                    settings.upload_dir,\n                )\n            except ValueError as exc:\n                return HTMLResponse(\n                    str(exc),\n                    status_code=400,\n                )\n\n            if photo_path:\n                sub.photo_path = photo_path\n\n        audit(\n            db,\n            request,\n            "edit_pending_submission",\n            "submission",\n            sub.id,\n            "admin-reviewed extracted details",\n        )\n\n        db.commit()\n\n    return RedirectResponse(\n        "/admin/submissions",\n        status_code=303,\n    )\n\n\n@router.post("/admin/submissions/{submission_id}/reject")\ndef reject_submission(request: Request, submission_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        sub = db.get(Submission, submission_id)\n        if sub:\n            sub.status = "rejected"\n            audit(db, request, "reject_submission", "submission", sub.id)\n            db.commit()\n    return RedirectResponse("/admin/submissions", status_code=303)\n\n\n@router.get("/admin/discovery", response_class=HTMLResponse)\ndef discovery_page(\n    request: Request,\n    disaster_id: int | None = None,\n    platform: str = "facebook",\n    view: str = "review",\n    q: str = "",\n    wide_queries: int | None = None,\n    wide_raw: int | None = None,\n    wide_added: int | None = None,\n    wide_error: int | None = None,\n):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    allowed_views = {"review", "relevant", "irrelevant", "processed"}\n    view = view.casefold().strip()\n    if view not in allowed_views:\n        view = "review"\n\n    with SessionLocal() as db:\n        disasters = list(\n            db.scalars(\n                select(Disaster).order_by(\n                    Disaster.active.desc(),\n                    Disaster.start_date.desc(),\n                )\n            ).all()\n        )\n        selected = (\n            db.get(Disaster, disaster_id)\n            if disaster_id\n            else next((d for d in disasters if d.active), disasters[0] if disasters else None)\n        )\n\n        queries = (\n            generate_queries(selected, platform=platform)\n            if selected\n            else []\n        )\n\n        wide_provider_status = serper_status()\n        wide_query_plan: list[str] = []\n        published_urls: set[str] = set()\n        queue_counts = {\n            "review": 0,\n            "relevant": 0,\n            "irrelevant": 0,\n            "processed": 0,\n        }\n        candidates: list[DiscoveryCandidate] = []\n\n        if selected:\n            if platform == "facebook":\n                scopes = collect_known_source_scopes(db, selected.id)\n                wide_query_plan = generate_wide_queries(\n                    selected,\n                    source_scopes=scopes,\n                )\n\n            published_urls = set(\n                db.scalars(\n                    select(Source.url)\n                    .join(MissingPerson, Source.person_id == MissingPerson.id)\n                    .where(\n                        MissingPerson.disaster_id == selected.id,\n                        MissingPerson.published.is_(True),\n                        MissingPerson.archived.is_(False),\n                    )\n                ).all()\n            )\n\n            base_conditions = [\n                DiscoveryCandidate.disaster_id == selected.id,\n                DiscoveryCandidate.platform == platform,\n            ]\n\n            status_groups = {\n                "review": ["new", "needs_ai"],\n                "relevant": ["relevant"],\n                "irrelevant": ["irrelevant", "rejected"],\n                "processed": ["reviewed"],\n            }\n\n            for key, statuses in status_groups.items():\n                count_stmt = (\n                    select(func.count(DiscoveryCandidate.id))\n                    .where(*base_conditions)\n                    .where(DiscoveryCandidate.status.in_(statuses))\n                )\n                if key in {"review", "relevant"} and published_urls:\n                    count_stmt = count_stmt.where(\n                        DiscoveryCandidate.url.notin_(published_urls)\n                    )\n                queue_counts[key] = db.scalar(count_stmt) or 0\n\n            stmt = (\n                select(DiscoveryCandidate)\n                .where(*base_conditions)\n                .where(DiscoveryCandidate.status.in_(status_groups[view]))\n                .order_by(DiscoveryCandidate.found_at.desc())\n            )\n\n            if view in {"review", "relevant"} and published_urls:\n                stmt = stmt.where(\n                    DiscoveryCandidate.url.notin_(published_urls)\n                )\n\n            if q.strip():\n                pattern = f"%{q.strip()}%"\n                stmt = stmt.where(\n                    or_(\n                        DiscoveryCandidate.title.ilike(pattern),\n                        DiscoveryCandidate.snippet.ilike(pattern),\n                    )\n                )\n\n            candidates = list(db.scalars(stmt.limit(300)).all())\n\n        base_params = {\n            "disaster_id": selected.id if selected else "",\n            "platform": platform,\n        }\n        queue_links = {\n            key: "/admin/discovery?" + urlencode(\n                {**base_params, "view": key, **({"q": q.strip()} if q.strip() else {})}\n            )\n            for key in allowed_views\n        }\n        clear_search_url = "/admin/discovery?" + urlencode(\n            {**base_params, "view": view}\n        )\n\n        return render(\n            request,\n            "admin_discovery.html",\n            disasters=disasters,\n            selected=selected,\n            platform=platform,\n            view=view,\n            q=q,\n            queue_counts=queue_counts,\n            queue_links=queue_links,\n            clear_search_url=clear_search_url,\n            queries=[(item, google_search_url(item, selected.start_date)) for item in queries] if selected else [],\n            candidates=candidates,\n            bot_message=None,\n            wide_stats=(\n                {"queries": wide_queries, "raw": wide_raw, "added": wide_added}\n                if wide_queries is not None\n                else None\n            ),\n            wide_provider_status=wide_provider_status,\n            wide_query_plan=wide_query_plan,\n            wide_error=bool(wide_error),\n        )\n\n\n@router.post("/admin/discovery/run")\nasync def discovery_run(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    disaster_id = parse_int(form.get("disaster_id"))\n    platform = str(form.get("platform") or "facebook")\n    with SessionLocal() as db:\n        disaster = db.get(Disaster, disaster_id) if disaster_id else None\n        if disaster is None:\n            return RedirectResponse("/admin/discovery", status_code=303)\n        added = discover_candidates(db, disaster, platform=platform)\n        audit(db, request, "run_discovery_bot", "disaster", disaster.id, f"platform={platform}; added={added}")\n        db.commit()\n    return RedirectResponse(f"/admin/discovery?disaster_id={disaster_id}&platform={platform}", status_code=303)\n\n\n\n@router.post("/admin/wide-discovery/run")\nasync def wide_discovery_run(\n    request: Request,\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    form = await request.form()\n\n    disaster_id = parse_int(\n        form.get("disaster_id")\n    )\n\n    with SessionLocal() as db:\n        disaster = (\n            db.get(\n                Disaster,\n                disaster_id,\n            )\n            if disaster_id\n            else None\n        )\n\n        if disaster is None:\n            return RedirectResponse(\n                "/admin/discovery",\n                status_code=303,\n            )\n\n        try:\n            stats = run_wide_discovery(\n                db,\n                disaster,\n            )\n        except SearchProviderUnavailable:\n            return RedirectResponse(\n                (\n                    "/admin/discovery"\n                    f"?disaster_id={disaster_id}"\n                    "&platform=facebook"\n                    "&wide_error=1"\n                ),\n                status_code=303,\n            )\n\n        audit(\n            db,\n            request,\n            "run_wide_discovery",\n            "disaster",\n            disaster.id,\n            (\n                f"queries={stats[\'queries\']}; "\n                f"raw={stats[\'raw_results\']}; "\n                f"needs_ai={stats[\'needs_ai\']}"\n            ),\n        )\n\n        db.commit()\n\n    return RedirectResponse(\n        (\n            "/admin/discovery"\n            f"?disaster_id={disaster_id}"\n            "&platform=facebook"\n            f"&wide_queries={stats[\'queries\']}"\n            f"&wide_raw={stats[\'raw_results\']}"\n            f"&wide_added={stats[\'needs_ai\']}"\n        ),\n        status_code=303,\n    )\n\n\n@router.post("/admin/discovery/manual")\nasync def discovery_manual(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    disaster_id = parse_int(form.get("disaster_id"))\n    url = canonicalize_url(str(form.get("url") or ""))\n    platform = str(form.get("platform") or "facebook")\n    if not disaster_id or not url:\n        return RedirectResponse("/admin/discovery", status_code=303)\n    with SessionLocal() as db:\n        existing = db.scalar(\n            select(DiscoveryCandidate).where(\n                DiscoveryCandidate.disaster_id == disaster_id, DiscoveryCandidate.url == url\n            )\n        )\n        if existing is None:\n            candidate = DiscoveryCandidate(\n                disaster_id=disaster_id,\n                platform=platform,\n                query="manual-url",\n                url=url,\n                title=str(form.get("title") or "").strip() or None,\n                snippet=str(form.get("snippet") or "").strip() or None,\n            )\n            db.add(candidate)\n            db.flush()\n            audit(db, request, "add_manual_candidate", "discovery_candidate", candidate.id, url)\n            db.commit()\n    return RedirectResponse(f"/admin/discovery?disaster_id={disaster_id}&platform={platform}", status_code=303)\n\n\n@router.post("/admin/discovery/{candidate_id}/status")\nasync def discovery_candidate_status(request: Request, candidate_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    form = await request.form()\n    action = str(form.get("status_action") or "").strip().casefold()\n    current_view = str(form.get("view") or "review").strip().casefold()\n    platform = str(form.get("platform") or "facebook").strip()\n    q = str(form.get("q") or "").strip()\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return HTMLResponse("Not found", status_code=404)\n\n        if candidate.status != "reviewed":\n            if action == "relevant":\n                candidate.status = "relevant"\n            elif action == "irrelevant":\n                candidate.status = "irrelevant"\n            elif action == "restore":\n                candidate.status = "needs_ai"\n            else:\n                return HTMLResponse("Invalid discovery status", status_code=400)\n\n            audit(\n                db,\n                request,\n                "classify_discovery_candidate",\n                "discovery_candidate",\n                candidate.id,\n                f"status={candidate.status}",\n            )\n            db.commit()\n\n        params = {\n            "disaster_id": candidate.disaster_id,\n            "platform": platform,\n            "view": current_view if current_view in {"review", "relevant", "irrelevant", "processed"} else "review",\n        }\n        if q:\n            params["q"] = q\n\n    return RedirectResponse(\n        "/admin/discovery?" + urlencode(params),\n        status_code=303,\n    )\n\n\n@router.get(\n    "/admin/discovery/{candidate_id}",\n    response_class=HTMLResponse,\n)\nasync def discovery_candidate_review(\n    request: Request,\n    candidate_id: int,\n):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return HTMLResponse("Not found", status_code=404)\n\n        disaster = db.get(Disaster, candidate.disaster_id)\n        if disaster is None:\n            return HTMLResponse("Unknown disaster", status_code=404)\n\n        source_image_url = None\n        ocr_text = ""\n        ocr_detail = None\n\n        if candidate.platform == "facebook":\n            source_image_url = await discover_public_post_image(candidate.url)\n\n        if source_image_url:\n            if ocr_available():\n                ocr_dir = settings.upload_dir / "_ocr_preview"\n                ocr_filename = await download_public_source_image(\n                    source_image_url,\n                    ocr_dir,\n                )\n                if ocr_filename:\n                    local_path = ocr_dir / ocr_filename\n                    result = extract_ocr_text(local_path)\n                    ocr_text = result.text\n                    ocr_detail = result.detail\n                    try:\n                        local_path.unlink(missing_ok=True)\n                        ocr_dir.rmdir()\n                    except OSError:\n                        pass\n            else:\n                ocr_detail = (\n                    "Local OCR is not available yet. Install Tesseract OCR "\n                    "and the Nepali language data to read poster text automatically."\n                )\n\n        prefill = extract_candidate_prefill(\n            candidate,\n            disaster,\n            ocr_text=ocr_text,\n        )\n\n        return render(\n            request,\n            "admin_discovery_review.html",\n            candidate=candidate,\n            prefill=prefill,\n            source_image_url=source_image_url,\n            ocr_text=ocr_text,\n            ocr_detail=ocr_detail,\n        )\n\n\n@router.post("/admin/discovery/{candidate_id}/submission")\nasync def discovery_to_submission(request: Request, candidate_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    form = await request.form()\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return HTMLResponse("Not found", status_code=404)\n        if candidate.status in {"irrelevant", "rejected"}:\n            return HTMLResponse(\n                "Restore this discovery candidate before creating a submission.",\n                status_code=409,\n            )\n\n        name = str(form.get("name") or "").strip()\n        location = str(form.get("last_seen_location") or "").strip()\n        if not name or not location:\n            return RedirectResponse(\n                f"/admin/discovery/{candidate_id}",\n                status_code=303,\n            )\n\n        source_image_url = str(form.get("source_image_url") or "").strip()\n        include_source_image = str(form.get("include_source_image") or "") == "1"\n        photo_path = None\n\n        if (\n            include_source_image\n            and source_image_url\n            and is_allowed_public_image_url(source_image_url)\n        ):\n            photo_path = await download_public_source_image(\n                source_image_url,\n                settings.upload_dir,\n            )\n\n        ocr_text = str(form.get("ocr_text") or "").strip()\n        notes_parts = [candidate.snippet or ""]\n        if ocr_text:\n            notes_parts.append("OCR text from reviewed source image:\\n" + ocr_text)\n        notes = "\\n\\n".join(part.strip() for part in notes_parts if part.strip()) or None\n\n        sub = Submission(\n            disaster_id=candidate.disaster_id,\n            kind="missing_report",\n            name=name,\n            photo_path=photo_path,\n            name_ne=str(form.get("name_ne") or "").strip() or None,\n            age=parse_int(form.get("age")),\n            gender=_normalize_gender(form.get("gender")),\n            last_seen_date=parse_date(form.get("last_seen_date")),\n            last_seen_time=parse_time(form.get("last_seen_time")),\n            last_seen_location=location,\n            clothing=str(form.get("clothing") or "").strip() or None,\n            identification_details=str(form.get("identification_details") or "").strip() or None,\n            public_contact_number=str(form.get("public_contact_number") or "").strip() or None,\n            social_url=candidate.url,\n            notes=notes,\n        )\n        db.add(sub)\n        candidate.status = "reviewed"\n        db.flush()\n        audit(\n            db,\n            request,\n            "candidate_to_submission",\n            "submission",\n            sub.id,\n            candidate.url,\n        )\n        db.commit()\n\n    return RedirectResponse("/admin/submissions", status_code=303)\n\n\n@router.get(\n    "/admin/ai-review",\n    response_class=HTMLResponse,\n)\ndef discovery_ai_review_page(\n    request: Request,\n    disaster_id: int,\n    platform: str = "facebook",\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    with SessionLocal() as db:\n        disaster = db.get(\n            Disaster,\n            disaster_id,\n        )\n\n        if disaster is None:\n            return HTMLResponse(\n                "Unknown disaster",\n                status_code=404,\n            )\n\n        candidates = list(\n            db.scalars(\n                select(DiscoveryCandidate)\n                .where(\n                    DiscoveryCandidate.disaster_id\n                    == disaster.id,\n                    DiscoveryCandidate.platform\n                    == platform,\n                    DiscoveryCandidate.status.in_(\n                        ["new", "needs_ai", "relevant"]\n                    ),\n                )\n                .order_by(\n                    DiscoveryCandidate.found_at.desc()\n                )\n                .limit(100)\n            ).all()\n        )\n\n        prompt = build_free_ai_review_prompt(\n            disaster,\n            candidates,\n        )\n\n        return render(\n            request,\n            "admin_ai_review.html",\n            disaster=disaster,\n            platform=platform,\n            candidates=candidates,\n            prompt=prompt,\n        )\n\n\n@router.post(\n    "/admin/ai-review/import"\n)\nasync def discovery_ai_review_import(\n    request: Request,\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    form = await request.form()\n\n    disaster_id = parse_int(\n        form.get("disaster_id")\n    )\n\n    platform = str(\n        form.get("platform") or "facebook"\n    ).strip()\n\n    raw_result = str(\n        form.get("result_json") or ""\n    ).strip()\n\n    if not disaster_id or not raw_result:\n        return HTMLResponse(\n            "Missing AI review data",\n            status_code=400,\n        )\n\n    try:\n        results = parse_free_ai_review(\n            raw_result\n        )\n    except ValueError:\n        return HTMLResponse(\n            "Invalid AI review JSON. "\n            "Return to Free AI Review and paste "\n            "the JSON response exactly.",\n            status_code=400,\n        )\n\n    created = 0\n    rejected = 0\n    uncertain = 0\n\n    downloaded_images: dict[str, str | None] = {}\n\n    with SessionLocal() as db:\n        disaster = db.get(\n            Disaster,\n            disaster_id,\n        )\n\n        if disaster is None:\n            return HTMLResponse(\n                "Unknown disaster",\n                status_code=404,\n            )\n\n        for result in results:\n            candidate = db.get(\n                DiscoveryCandidate,\n                result["candidate_id"],\n            )\n\n            # AI output never gets authority to change\n            # disaster/source identity.\n            if candidate is None:\n                continue\n\n            if (\n                candidate.disaster_id\n                != disaster.id\n            ):\n                continue\n\n            if candidate.platform != platform:\n                continue\n\n            if candidate.status not in {\n                "new",\n                "needs_ai",\n                "relevant",\n            }:\n                continue\n\n            decision = result["decision"]\n\n            if decision == "reject":\n                candidate.status = "irrelevant"\n                rejected += 1\n                continue\n\n            if decision == "uncertain":\n                uncertain += 1\n                continue\n\n            accepted_person = False\n\n            for person_data in result["people"]:\n                name = str(\n                    person_data.get("name")\n                    or ""\n                ).strip()\n\n                if not name:\n                    continue\n\n                accepted_person = True\n\n                existing = db.scalar(\n                    select(Submission.id).where(\n                        Submission.disaster_id\n                        == disaster.id,\n                        Submission.social_url\n                        == candidate.url,\n                        Submission.name\n                        == name,\n                    )\n                )\n\n                if existing:\n                    continue\n\n                image_url = str(\n                    person_data.get(\n                        "image_url"\n                    )\n                    or ""\n                ).strip()\n\n                photo_path = None\n\n                if (\n                    image_url\n                    and is_allowed_public_image_url(\n                        image_url\n                    )\n                ):\n                    if (\n                        image_url\n                        not in downloaded_images\n                    ):\n                        downloaded_images[\n                            image_url\n                        ] = (\n                            await download_public_source_image(\n                                image_url,\n                                settings.upload_dir,\n                            )\n                        )\n\n                    photo_path = (\n                        downloaded_images[\n                            image_url\n                        ]\n                    )\n\n                reason = result.get(\n                    "reason"\n                ) or ""\n\n                confidence = result.get(\n                    "confidence"\n                )\n\n                notes = (\n                    candidate.snippet\n                    or ""\n                ).strip()\n\n                ai_note = (\n                    f"Free AI review: {reason}"\n                )\n\n                if confidence is not None:\n                    ai_note += (\n                        f" | confidence={confidence}"\n                    )\n\n                if (\n                    image_url\n                    and is_allowed_public_image_url(\n                        image_url\n                    )\n                ):\n                    ai_note += (\n                        f" | source_image_url={image_url}"\n                    )\n\n                if notes:\n                    notes = (\n                        notes\n                        + "\\n\\n"\n                        + ai_note\n                    )\n                else:\n                    notes = ai_note\n\n                submission = Submission(\n                    disaster_id=disaster.id,\n                    kind="missing_report",\n                    name=name,\n                    photo_path=photo_path,\n                    name_ne=(\n                        str(\n                            person_data.get(\n                                "name_ne"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    age=parse_int(\n                        person_data.get("age")\n                    ),\n                    gender=_normalize_gender(person_data.get("gender")),\n                    last_seen_date=parse_date(\n                        person_data.get(\n                            "last_seen_date"\n                        )\n                    ),\n                    last_seen_time=parse_time(\n                        person_data.get(\n                            "last_seen_time"\n                        )\n                    ),\n                    last_seen_location=(\n                        str(\n                            person_data.get(\n                                "last_seen_location"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    clothing=(\n                        str(\n                            person_data.get(\n                                "clothing"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    identification_details=(\n                        str(\n                            person_data.get(\n                                "identification_details"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    public_contact_number=(\n                        str(\n                            person_data.get(\n                                "public_contact_number"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    social_url=candidate.url,\n                    notes=notes,\n                )\n\n                db.add(submission)\n                created += 1\n\n            if accepted_person:\n                candidate.status = "reviewed"\n\n        audit(\n            db,\n            request,\n            "import_free_ai_review",\n            "disaster",\n            disaster.id,\n            (\n                f"platform={platform}; "\n                f"submissions={created}; "\n                f"rejected={rejected}; "\n                f"uncertain={uncertain}"\n            ),\n        )\n\n        db.commit()\n\n    return RedirectResponse(\n        "/admin/submissions",\n        status_code=303,\n    )\n\n\n@router.get("/admin/export", response_class=HTMLResponse)\ndef export_page(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        return render(request, "admin_export.html", disasters=disasters)\n\n\n@router.get("/admin/export/{file_type}")\ndef export_data(request: Request, file_type: str, disaster_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    if file_type not in {"csv", "xlsx"}:\n        return HTMLResponse("Unsupported export", status_code=400)\n    with SessionLocal() as db:\n        disaster = db.get(Disaster, disaster_id)\n        if disaster is None:\n            return HTMLResponse("Unknown disaster", status_code=404)\n        if file_type == "csv":\n            data = build_csv(db, disaster_id)\n            media = "text/csv; charset=utf-8"\n        else:\n            data = build_xlsx(db, disaster_id)\n            media = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"\n        audit(db, request, "export", "disaster", disaster_id, file_type)\n        db.commit()\n        filename = f"{disaster.code.lower()}-missing-people.{file_type}"\n        return Response(\n            data,\n            media_type=media,\n            headers={"Content-Disposition": f\'attachment; filename="{filename}"\'},\n        )\n\n\n@router.get("/admin/people/{person_id}/share-card")\ndef share_card(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person is None:\n            return HTMLResponse("Not found", status_code=404)\n        image = build_share_card(person)\n        audit(db, request, "generate_share_card", "person", person.id)\n        db.commit()\n        return Response(\n            image,\n            media_type="image/png",\n            headers={"Content-Disposition": f\'inline; filename="{person.case_number}.png"\'},\n        )\n', 'app/services/candidate_extract.py': 'from __future__ import annotations\n\nimport re\nfrom datetime import datetime\nfrom typing import Any\n\nfrom ..models import Disaster, DiscoveryCandidate\n\n\nNEPALI_DIGITS = str.maketrans("०१२३४५६७८९", "0123456789")\n\nPHONE_RE = re.compile(\n    r"(?<!\\d)(?:\\+?977[-\\s]?)?(9\\d(?:[\\s-]?\\d){8})(?!\\d)"\n)\n\nAGE_PATTERNS = [\n    re.compile(r"\\bage\\s*[:\\-]?\\s*(\\d{1,3})\\b", re.IGNORECASE),\n    re.compile(r"\\b(\\d{1,3})\\s*years?\\s*old\\b", re.IGNORECASE),\n    re.compile(r"\\b(\\d{1,3})\\s*(?:yrs?|y/o)\\b", re.IGNORECASE),\n    re.compile(r"\\bउमेर\\s*[:\\-]?\\s*(\\d{1,3})\\b"),\n    re.compile(r"\\((\\d{1,3})\\)"),\n]\n\nNAME_PATTERNS = [\n    re.compile(\n        r"\\bPerson\\s+Missing\\s+"\n        r"(?:Mr\\.?|Ms\\.?|Mrs\\.?|Er\\.?)?\\s*"\n        r"([A-Z][A-Za-z\'.-]+(?:\\s+[A-Z][A-Za-z\'.-]+){1,4})",\n        re.IGNORECASE,\n    ),\n    re.compile(\n        r"\\bMissing\\s+Person\\s*[:\\-]?\\s*"\n        r"(?:Mr\\.?|Ms\\.?|Mrs\\.?|Er\\.?)?\\s*"\n        r"([A-Z][A-Za-z\'.-]+(?:\\s+[A-Z][A-Za-z\'.-]+){1,4})",\n        re.IGNORECASE,\n    ),\n    re.compile(\n        r"\\bName\\s*[:\\-]\\s*"\n        r"([A-Z][A-Za-z\'.-]+(?:\\s+[A-Z][A-Za-z\'.-]+){1,4})",\n        re.IGNORECASE,\n    ),\n]\n\nNEPALI_NAME_RE = re.compile(\n    r"(?:नाम|नाम थर)\\s*[:\\-]?\\s*([\\u0900-\\u097F][\\u0900-\\u097F\\s.\'’-]{1,100})"\n)\n\nSTOP_WORDS = {\n    "was", "is", "has", "who", "from", "working", "works", "last",\n    "missing", "person", "people", "out", "contact", "facebook",\n}\n\nDETAIL_KEYWORDS = (\n    "address", "resident", "residence", "home", "work", "works", "working",\n    "workplace", "occupation", "profession", "employee", "engineer", "driver",\n    "guide", "bank", "hydropower", "hotel", "guest house", "family", "father",\n    "mother", "son", "daughter", "brother", "sister", "husband", "wife",\n    "travel", "travelling", "traveling", "route", "vehicle", "bike", "car",\n    "ठेगाना", "बसोबास", "पेशा", "कार्यरत", "काम", "परिवार", "बुबा", "आमा",\n    "छोरा", "छोरी", "दाजु", "भाइ", "दिदी", "बहिनी", "यात्रा", "सवारी",\n)\n\n\ndef _normalize_digits(text: str) -> str:\n    return text.translate(NEPALI_DIGITS)\n\n\ndef _clean_name(value: str) -> str:\n    words = value.strip(" ,-–—.").split()\n    cleaned: list[str] = []\n\n    for word in words:\n        if word.casefold().rstrip(".,") in STOP_WORDS:\n            break\n        cleaned.append(word.strip(" ,-–—."))\n\n    while cleaned and cleaned[0].casefold().rstrip(".") in {"mr", "mrs", "ms", "er"}:\n        cleaned.pop(0)\n\n    return " ".join(cleaned).strip()\n\n\ndef _extract_name(title: str, snippet: str, ocr_text: str = "") -> str | None:\n    # Title is intentionally searched first because search-engine snippets can\n    # sometimes contain text stitched from another post.\n    for source in (title, snippet, ocr_text):\n        if not source:\n            continue\n        for pattern in NAME_PATTERNS:\n            match = pattern.search(source)\n            if match:\n                value = _clean_name(match.group(1))\n                if 2 <= len(value.split()) <= 5:\n                    return value\n\n    for nepali_term in ("सम्पर्कविहीन", "सम्पर्क विहीन", "बेपत्ता", "हराएको"):\n        if nepali_term not in title:\n            continue\n        before = title.split(nepali_term, 1)[0]\n        if " - " in before:\n            before = before.split(" - ")[-1]\n        before = re.sub(\n            r"^(?:Mr|Mrs|Ms|Er)\\.?\\s+",\n            "",\n            before.strip(),\n            flags=re.IGNORECASE,\n        )\n        value = _clean_name(before)\n        if 2 <= len(value.split()) <= 5:\n            return value\n\n    return None\n\n\ndef _extract_nepali_name(text: str) -> str | None:\n    match = NEPALI_NAME_RE.search(text)\n    if not match:\n        return None\n    value = re.split(r"[\\n|,;]", match.group(1), maxsplit=1)[0].strip(" .,:;-–—")\n    words = value.split()\n    if 1 <= len(words) <= 6:\n        return value[:255]\n    return None\n\n\ndef _extract_age(text: str) -> int | None:\n    text = _normalize_digits(text)\n    for pattern in AGE_PATTERNS:\n        match = pattern.search(text)\n        if not match:\n            continue\n        try:\n            age = int(match.group(1))\n        except ValueError:\n            continue\n        if 0 < age < 120:\n            return age\n    return None\n\n\ndef _extract_phones(text: str) -> str | None:\n    text = _normalize_digits(text)\n    found: list[str] = []\n    for match in PHONE_RE.finditer(text):\n        number = re.sub(r"\\D", "", match.group(1))\n        if len(number) == 10 and number not in found:\n            found.append(number)\n        if len(found) >= 3:\n            break\n    return ", ".join(found) if found else None\n\n\ndef _clean_location(value: str) -> str | None:\n    value = re.sub(\n        r"^\\s*(?:at\\s+)?\\d{1,2}(?::\\d{2})?\\s*(?:am|pm)?\\s*(?:in|at)?\\s*",\n        "",\n        value,\n        flags=re.IGNORECASE,\n    )\n    value = re.sub(\n        r"\\s+at\\s+\\d{1,2}(?::\\d{2})?\\s*(?:am|pm)?\\s*$",\n        "",\n        value,\n        flags=re.IGNORECASE,\n    )\n    value = re.split(\n        r"\\b(?:and|who|has|was|is|since|after|before|please|contact)\\b",\n        value,\n        maxsplit=1,\n        flags=re.IGNORECASE,\n    )[0]\n    value = value.strip(" ,.;:-–—")\n    return value[:250] if value else None\n\n\ndef _extract_location(text: str, disaster: Disaster) -> str | None:\n    explicit_patterns = [\n        re.compile(r"\\blast\\s+known\\s+location\\s*[:\\-]?\\s*([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"\\blast\\s+known\\s+to\\s+be\\s+in\\s+([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"\\blast\\s+seen(?:\\s+location)?\\s*[:\\-]\\s*([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"\\blast\\s+seen\\s+(?:at|in)\\s+([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"\\bmissing\\s+from\\s+([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"\\blocation\\s*[:\\-]\\s*([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"(?:अन्तिम\\s+पटक\\s+देखिएको\\s+स्थान|हराएको\\s+स्थान|स्थान)\\s*[:\\-]?\\s*([^.;\\n]+)"),\n    ]\n\n    for pattern in explicit_patterns:\n        match = pattern.search(text)\n        if match:\n            value = _clean_location(match.group(1))\n            if value and not re.fullmatch(r"\\d{1,2}(?::\\d{2})?\\s*(?:am|pm)?", value, re.IGNORECASE):\n                return value\n\n    folded = text.casefold()\n    matches = [\n        location\n        for location in disaster.locations()\n        if location.casefold() in folded\n    ]\n    if matches:\n        generic_tokens = {token.casefold() for token in disaster.name.split()}\n        specific = [\n            location\n            for location in matches\n            if location.casefold() not in generic_tokens\n        ]\n        if specific:\n            matches = specific\n        return sorted(matches, key=len, reverse=True)[0]\n\n    workplace = re.search(r"\\bworks?\\s+at\\s+([^.;\\n]+)", text, re.IGNORECASE)\n    if workplace:\n        return _clean_location(workplace.group(1))\n\n    return None\n\n\ndef _extract_gender(text: str) -> str | None:\n    match = re.search(r"\\bgender\\s*[:\\-]\\s*(male|female)\\b", text, re.IGNORECASE)\n    if match:\n        return "Male" if match.group(1).casefold() == "male" else "Female"\n\n    match = re.search(r"(?:लिङ्ग|लिंग)\\s*[:\\-]?\\s*(पुरुष|महिला)\\b", text)\n    if match:\n        return "Male" if match.group(1) == "पुरुष" else "Female"\n\n    return None\n\n\ndef _extract_time(text: str) -> str | None:\n    text = _normalize_digits(text)\n    patterns = [\n        re.compile(\n            r"(?:last\\s+(?:seen|contacted)|time)\\D{0,25}"\n            r"(\\d{1,2})(?::(\\d{2}))?\\s*(am|pm)\\b",\n            re.IGNORECASE,\n        ),\n        re.compile(\n            r"(?:last\\s+(?:seen|contacted)|time)\\D{0,25}"\n            r"([01]?\\d|2[0-3]):([0-5]\\d)\\b",\n            re.IGNORECASE,\n        ),\n        re.compile(r"\\b(\\d{1,2}):(\\d{2})\\s*(am|pm)\\b", re.IGNORECASE),\n    ]\n\n    for pattern in patterns:\n        match = pattern.search(text)\n        if not match:\n            continue\n        groups = match.groups()\n        try:\n            hour = int(groups[0])\n            minute = int(groups[1] or 0)\n        except (TypeError, ValueError):\n            continue\n        ampm = groups[2].casefold() if len(groups) >= 3 and groups[2] else None\n        if ampm:\n            if not 1 <= hour <= 12 or not 0 <= minute <= 59:\n                continue\n            if ampm == "pm" and hour != 12:\n                hour += 12\n            if ampm == "am" and hour == 12:\n                hour = 0\n        elif not (0 <= hour <= 23 and 0 <= minute <= 59):\n            continue\n        return f"{hour:02d}:{minute:02d}"\n\n    return None\n\n\ndef _extract_date(text: str) -> str | None:\n    text = _normalize_digits(text)\n    patterns = [\n        (re.compile(r"\\b(20\\d{2})[-/](\\d{1,2})[-/](\\d{1,2})\\b"), "%Y-%m-%d"),\n        (re.compile(r"\\b(\\d{1,2})[/-](\\d{1,2})[/-](20\\d{2})\\b"), "%d-%m-%Y"),\n    ]\n\n    for pattern, kind in patterns:\n        match = pattern.search(text)\n        if not match:\n            continue\n        try:\n            if kind == "%Y-%m-%d":\n                value = datetime(int(match.group(1)), int(match.group(2)), int(match.group(3)))\n            else:\n                value = datetime(int(match.group(3)), int(match.group(2)), int(match.group(1)))\n        except ValueError:\n            continue\n        return value.date().isoformat()\n\n    month_match = re.search(\n        r"\\b(?:last\\s+(?:seen|contacted)\\s*(?:on|since)?\\s*)?"\n        r"(January|February|March|April|May|June|July|August|September|October|November|December)"\n        r"\\s+(\\d{1,2})(?:st|nd|rd|th)?[,]?\\s+(20\\d{2})\\b",\n        text,\n        re.IGNORECASE,\n    )\n    if month_match:\n        try:\n            value = datetime.strptime(\n                f"{month_match.group(1)} {month_match.group(2)} {month_match.group(3)}",\n                "%B %d %Y",\n            )\n            return value.date().isoformat()\n        except ValueError:\n            pass\n\n    return None\n\n\ndef _extract_clothing(text: str) -> str | None:\n    patterns = [\n        re.compile(r"\\b(?:last\\s+seen\\s+)?wearing\\s+([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"\\bclothing\\s*[:\\-]\\s*([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"(?:लगाएको\\s+लुगा|पोशाक|लुगा)\\s*[:\\-]?\\s*([^.;\\n]+)"),\n    ]\n    for pattern in patterns:\n        match = pattern.search(text)\n        if match:\n            value = match.group(1).strip(" ,.;:-–—")\n            if value:\n                return value[:1000]\n    return None\n\n\ndef _build_identification_details(snippet: str, ocr_text: str, combined: str) -> str | None:\n    details: list[str] = []\n\n    def has_detail_keyword(piece: str) -> bool:\n        for keyword in DETAIL_KEYWORDS:\n            if keyword.isascii():\n                if re.search(r"\\b" + re.escape(keyword) + r"\\b", piece, re.IGNORECASE):\n                    return True\n            elif keyword in piece:\n                return True\n        return False\n\n    def add(label: str, value: str) -> None:\n        value = " ".join(value.split()).strip()\n        if not value:\n            return\n        entry = f"{label}: {value}"\n        if entry not in details:\n            details.append(entry)\n\n    if snippet.strip():\n        add("Source snippet", snippet[:1800])\n\n    for piece in re.split(r"[\\n\\r]+|(?<=[.!?])\\s+", combined):\n        if has_detail_keyword(piece):\n            add("Other source detail", piece[:700])\n        if len(details) >= 8:\n            break\n\n    if ocr_text.strip():\n        add("OCR text", ocr_text[:3000])\n\n    return "\\n".join(details) or None\n\n\ndef extract_candidate_prefill(\n    candidate: DiscoveryCandidate,\n    disaster: Disaster,\n    ocr_text: str = "",\n) -> dict[str, Any]:\n    """Extract only information explicitly present in public text/OCR.\n\n    OCR reads written text from an image. Nothing is inferred from a person\'s\n    face, appearance, or name.\n    """\n    title = candidate.title or ""\n    snippet = candidate.snippet or ""\n    combined = "\\n".join(part for part in (title, snippet, ocr_text) if part).strip()\n    normalized = _normalize_digits(combined)\n\n    name_ne = _extract_nepali_name(normalized)\n    name = _extract_name(title, snippet, ocr_text)\n    if name is None and name_ne:\n        # The master record requires a name. A written Nepali name is valid\n        # source text, so use it rather than inventing a transliteration.\n        name = name_ne\n\n    return {\n        "name": name,\n        "name_ne": name_ne,\n        "age": _extract_age(normalized),\n        "gender": _extract_gender(normalized),\n        "last_seen_date": _extract_date(normalized),\n        "last_seen_time": _extract_time(normalized),\n        "last_seen_location": _extract_location(normalized, disaster),\n        "clothing": _extract_clothing(normalized),\n        "identification_details": _build_identification_details(\n            snippet,\n            ocr_text,\n            normalized,\n        ),\n        "public_contact_number": _extract_phones(normalized),\n    }\n', 'app/services/wide_discovery.py': 'from __future__ import annotations\n\nimport time\nfrom datetime import timedelta\nfrom typing import Protocol\nfrom urllib.parse import urlparse\n\nimport httpx\nfrom sqlalchemy import select\nfrom sqlalchemy.orm import Session\n\nfrom ..models import Disaster, DiscoveryCandidate\nfrom .discovery import SearchResult, is_person_specific_candidate\nfrom .normalization import canonicalize_url\nfrom .search_providers import SerperPublicSearch\n\n\nclass SearchProvider(Protocol):\n    def search(\n        self,\n        query: str,\n        max_results: int = 15,\n    ) -> list[SearchResult]:\n        ...\n\n\nWIDE_MAX_QUERIES = 40\nWIDE_RESULTS_PER_QUERY = 15\nWIDE_REQUEST_DELAY_SECONDS = 0.40\n\n\nPRECISION_TERMS = [\n    "out of contact",\n    "last seen",\n    "has been missing",\n    "person missing",\n    "cannot be contacted",\n    "सम्पर्कविहीन",\n    "सम्पर्क विहीन",\n    "बेपत्ता",\n    "खोजिदिनुहोला",\n    "हराएको व्यक्ति",\n]\n\nLIST_TERMS = [\n    "missing persons list",\n    "missing people names",\n    "named missing people",\n    "missing family",\n    "बेपत्ता नामावली",\n    "सम्पर्कविहीन नाम",\n    "हराएका व्यक्तिको सूची",\n]\n\nSOURCE_TERMS = [\n    "out of contact",\n    "last seen",\n    "person missing",\n    "सम्पर्कविहीन",\n    "बेपत्ता",\n    "खोजिदिनुहोला",\n]\n\n\ndef is_facebook_post_url(url: str) -> bool:\n    try:\n        parsed = urlparse(url)\n    except ValueError:\n        return False\n\n    host = (parsed.hostname or "").casefold()\n    if not (host == "facebook.com" or host.endswith(".facebook.com")):\n        return False\n\n    path = parsed.path.casefold()\n    return (\n        "/posts/" in path\n        or "/groups/" in path and "/posts/" in path\n        or "permalink.php" in path\n        or "story.php" in path\n        or "/photos/" in path\n        or "/photo/" in path\n        or "/reel/" in path\n        or "/reels/" in path\n        or "/share/p/" in path\n        or "/share/v/" in path\n    )\n\n\ndef facebook_source_scope(url: str) -> str | None:\n    try:\n        parsed = urlparse(url)\n    except ValueError:\n        return None\n\n    host = (parsed.hostname or "").casefold()\n    if not (host == "facebook.com" or host.endswith(".facebook.com")):\n        return None\n\n    parts = [part for part in parsed.path.split("/") if part]\n    if not parts:\n        return None\n\n    if parts[0].casefold() == "groups" and len(parts) >= 2:\n        return f"groups/{parts[1]}"\n\n    blocked = {\n        "watch", "reel", "reels", "photo", "photos", "share",\n        "story.php", "permalink.php",\n    }\n    if parts[0].casefold() in blocked:\n        return None\n\n    return parts[0]\n\n\ndef _unique(items: list[str]) -> list[str]:\n    output: list[str] = []\n    seen: set[str] = set()\n    for item in items:\n        normalized = " ".join(item.split())\n        if not normalized or normalized in seen:\n            continue\n        seen.add(normalized)\n        output.append(normalized)\n    return output\n\n\ndef _round_robin(groups: list[list[str]], max_queries: int) -> list[str]:\n    indexes = [0 for _ in groups]\n    output: list[str] = []\n    seen: set[str] = set()\n\n    while len(output) < max_queries:\n        added = False\n        for group_index, group in enumerate(groups):\n            while indexes[group_index] < len(group):\n                query = group[indexes[group_index]]\n                indexes[group_index] += 1\n                if query in seen:\n                    continue\n                seen.add(query)\n                output.append(query)\n                added = True\n                break\n            if len(output) >= max_queries:\n                break\n        if not added:\n            break\n\n    return output\n\n\ndef generate_wide_queries(\n    disaster: Disaster,\n    source_scopes: list[str] | None = None,\n    max_queries: int = WIDE_MAX_QUERIES,\n) -> list[str]:\n    """Generate a bounded, person-focused Facebook search plan.\n\n    Broad standalone ``missing`` searches are intentionally excluded. Every\n    query is constrained to Facebook, an event/location, a stronger\n    missing-person phrase, and the disaster time window.\n    """\n    locations = disaster.locations()\n    search_places = _unique([disaster.name, *locations])\n    event_root = (\n        disaster.name.replace("Flood", "").replace("flood", "").strip()\n        or disaster.name\n    )\n    after = (disaster.start_date - timedelta(days=1)).isoformat()\n    date_filter = f"after:{after}"\n\n    location_queries: list[str] = []\n    for place in search_places:\n        for term in PRECISION_TERMS:\n            location_queries.append(\n                f\'site:facebook.com "{place}" "{term}" {date_filter}\'\n            )\n\n    list_queries: list[str] = []\n    for term in LIST_TERMS:\n        list_queries.append(\n            f\'site:facebook.com "{event_root}" "{term}" {date_filter}\'\n        )\n\n    source_queries: list[str] = []\n    # Human-confirmed productive sources get a reserved slice of the budget.\n    for scope in source_scopes or []:\n        for term in SOURCE_TERMS:\n            source_queries.append(\n                f\'site:facebook.com/{scope} "{event_root}" "{term}" {date_filter}\'\n            )\n        for place in locations[:4]:\n            for term in ("out of contact", "सम्पर्कविहीन", "बेपत्ता"):\n                source_queries.append(\n                    f\'site:facebook.com/{scope} "{place}" "{term}" {date_filter}\'\n                )\n\n    location_queries = _unique(location_queries)\n    list_queries = _unique(list_queries)\n    source_queries = _unique(source_queries)\n\n    # Location results dominate, while confirmed sources and named lists are\n    # guaranteed space. The hard cap is never exceeded.\n    return _round_robin(\n        [location_queries, source_queries, location_queries, list_queries],\n        max_queries,\n    )\n\n\ndef collect_known_source_scopes(\n    db: Session,\n    disaster_id: int,\n    limit: int = 30,\n) -> list[str]:\n    """Return only sources promoted by human/processed relevance.\n\n    Irrelevant and unreviewed candidates must not teach the discovery engine\n    that a noisy page is productive.\n    """\n    urls = list(\n        db.scalars(\n            select(DiscoveryCandidate.url)\n            .where(\n                DiscoveryCandidate.disaster_id == disaster_id,\n                DiscoveryCandidate.status.in_(["relevant", "reviewed"]),\n            )\n            .order_by(DiscoveryCandidate.found_at.desc())\n            .limit(500)\n        ).all()\n    )\n\n    scopes: list[str] = []\n    for url in urls:\n        scope = facebook_source_scope(url)\n        if scope and scope not in scopes:\n            scopes.append(scope)\n        if len(scopes) >= limit:\n            break\n    return scopes\n\n\ndef _is_source_scoped_query(query: str) -> bool:\n    prefix = "site:facebook.com/"\n    return query.casefold().startswith(prefix) and not query.casefold().startswith(\n        "site:facebook.com \\"")\n\n\ndef run_wide_discovery(\n    db: Session,\n    disaster: Disaster,\n    provider: SearchProvider | None = None,\n    max_queries: int = WIDE_MAX_QUERIES,\n    request_delay_seconds: float = WIDE_REQUEST_DELAY_SECONDS,\n) -> dict[str, int]:\n    provider = provider or SerperPublicSearch()\n\n    scopes = collect_known_source_scopes(db, disaster.id)\n    queries = generate_wide_queries(\n        disaster,\n        source_scopes=scopes,\n        max_queries=max_queries,\n    )\n\n    searched = 0\n    raw_results = 0\n    accepted_for_ai = 0\n    seen_urls: set[str] = set()\n\n    for index, query in enumerate(queries):\n        searched += 1\n        try:\n            results = provider.search(\n                query,\n                max_results=WIDE_RESULTS_PER_QUERY,\n            )\n        except httpx.HTTPError:\n            continue\n\n        for result in results:\n            raw_results += 1\n            url = canonicalize_url(result.url)\n            if not url or url in seen_urls:\n                continue\n            seen_urls.add(url)\n\n            if not is_facebook_post_url(url):\n                continue\n\n            normalized_result = SearchResult(\n                url=url,\n                title=result.title,\n                snippet=result.snippet,\n            )\n\n            # Normal searches require explicit event context in the indexed\n            # text. Human-confirmed source sweeps may omit it, but still need\n            # strong person-level evidence.\n            if not is_person_specific_candidate(\n                normalized_result,\n                disaster,\n                require_event_context=not _is_source_scoped_query(query),\n            ):\n                continue\n\n            existing = db.scalar(\n                select(DiscoveryCandidate.id).where(\n                    DiscoveryCandidate.disaster_id == disaster.id,\n                    DiscoveryCandidate.url == url,\n                )\n            )\n            if existing:\n                continue\n\n            db.add(\n                DiscoveryCandidate(\n                    disaster_id=disaster.id,\n                    platform="facebook",\n                    query="wide:" + query,\n                    url=url,\n                    title=result.title,\n                    snippet=result.snippet,\n                    status="needs_ai",\n                )\n            )\n            accepted_for_ai += 1\n\n        if request_delay_seconds > 0 and index < len(queries) - 1:\n            time.sleep(request_delay_seconds)\n\n    return {\n        "queries": searched,\n        "raw_results": raw_results,\n        "needs_ai": accepted_for_ai,\n    }\n', 'app/services/discovery.py': 'from __future__ import annotations\n\nimport re\nimport time\nfrom dataclasses import dataclass\nfrom datetime import date, timedelta\nfrom urllib.parse import parse_qs, quote_plus, unquote, urlparse\n\nimport httpx\nfrom bs4 import BeautifulSoup\n\nfrom ..config import settings\nfrom sqlalchemy import select\nfrom sqlalchemy.orm import Session\n\nfrom ..models import Disaster, DiscoveryCandidate\nfrom .normalization import canonicalize_url, location_terms\n\nNEPALI_KEYWORDS = [\n    "सम्पर्कविहीन",\n    "सम्पर्क विहीन",\n    "बेपत्ता",\n    "हराएको",\n    "हराइरहेको",\n    "खोजिदिनुहोला",\n    "सम्पर्क गर्नुहोला",\n]\nENGLISH_KEYWORDS = [\n    "missing person",\n    "missing",\n    "out of contact",\n    "unaccounted for",\n    "please help find",\n    "last seen",\n]\n\nPLATFORM_SITE_FILTERS = {\n    "facebook": "site:facebook.com",\n    "instagram": "site:instagram.com",\n    "tiktok": "site:tiktok.com",\n    "x": "site:x.com",\n    "reddit": "site:reddit.com",\n    "web": "",\n}\n\n\n@dataclass(slots=True)\nclass SearchResult:\n    url: str\n    title: str\n    snippet: str\n\n\ndef generate_queries(\n    disaster: Disaster,\n    platform: str = "facebook",\n    max_queries: int | None = None,\n) -> list[str]:\n    """Generate bounded discovery searches.\n\n    Facebook discovery deliberately mixes:\n      - normal human-style searches\n      - site-constrained searches\n      - English\n      - Nepali\n      - high-precision name/list searches\n\n    The relevance gate later decides whether a result is actually\n    a missing-person notice.\n    """\n    max_queries = (\n        max_queries\n        or settings.discovery_max_queries_per_run\n    )\n\n    locations = (\n        disaster.locations()\n        or [disaster.name]\n    )\n\n    queries: list[str] = []\n    seen: set[str] = set()\n\n    def add(query: str) -> bool:\n        query = query.strip()\n\n        if not query or query in seen:\n            return False\n\n        seen.add(query)\n        queries.append(query)\n\n        return len(queries) >= max_queries\n\n    if platform == "facebook":\n\n        # ----------------------------------------------------\n        # PASS 1\n        #\n        # Reproduce natural searches while spreading different\n        # missing-person terms across affected locations.\n        #\n        # Example:\n        # facebook missing person Rasuwa flood\n        # site:facebook.com Rasuwa missing person flood\n        # facebook missing Timure flood\n        # facebook बेपत्ता Rasuwagadhi flood\n        # ----------------------------------------------------\n\n        core_keywords = [\n            "out of contact",\n            "last seen",\n            "बेपत्ता",\n            "सम्पर्कविहीन",\n        ]\n\n        for index, location in enumerate(locations):\n            keyword = core_keywords[\n                index % len(core_keywords)\n            ]\n\n            if add(\n                f"facebook {keyword} "\n                f"{location} "\n                f"{disaster.disaster_type}"\n            ):\n                return queries\n\n            if add(\n                f"site:facebook.com "\n                f"{location} "\n                f"{keyword} "\n                f"{disaster.disaster_type}"\n            ):\n                return queries\n\n        # ----------------------------------------------------\n        # PASS 2\n        #\n        # Higher precision searches for names, lists,\n        # last-seen notices and direct appeals.\n        # ----------------------------------------------------\n\n        precision_phrases = [\n            "missing person name",\n            "missing persons list",\n            "missing people names",\n            "missing since last seen",\n            "please share missing person",\n            "बेपत्ता नामावली",\n            "सम्पर्कविहीन नाम",\n            "हराएको व्यक्ति",\n        ]\n\n        for phrase in precision_phrases:\n            for location in locations:\n\n                if add(\n                    f"facebook {phrase} "\n                    f"{location} "\n                    f"{disaster.disaster_type}"\n                ):\n                    return queries\n\n                if add(\n                    f"site:facebook.com "\n                    f"{location} "\n                    f"{phrase} "\n                    f"{disaster.disaster_type}"\n                ):\n                    return queries\n\n        return queries\n\n    # --------------------------------------------------------\n    # OTHER PLATFORMS\n    # --------------------------------------------------------\n\n    site = PLATFORM_SITE_FILTERS.get(\n        platform,\n        "",\n    )\n\n    platform_name = (\n        "twitter"\n        if platform == "x"\n        else platform\n    )\n\n    keywords = (\n        NEPALI_KEYWORDS\n        + ENGLISH_KEYWORDS\n    )\n\n    for keyword in keywords:\n        for location in locations:\n\n            if add(\n                " ".join(\n                    part\n                    for part in [\n                        platform_name,\n                        keyword,\n                        location,\n                        disaster.disaster_type,\n                    ]\n                    if part\n                )\n            ):\n                return queries\n\n            if site:\n                if add(\n                    f"{site} "\n                    f"{location} "\n                    f"{keyword} "\n                    f"{disaster.disaster_type}"\n                ):\n                    return queries\n\n    return queries\n\ndef google_search_url(query: str, start_date: date | None = None, window_days: int = 7) -> str:\n    if start_date is not None:\n        before = start_date + timedelta(days=max(window_days, 1))\n        query = f"{query} after:{start_date.isoformat()} before:{before.isoformat()}"\n    return f"https://www.google.com/search?q={quote_plus(query)}"\n\n\ndef _decode_ddg_url(href: str) -> str:\n    parsed = urlparse(href)\n    if parsed.netloc.endswith("duckduckgo.com") and parsed.path.startswith("/l/"):\n        target = parse_qs(parsed.query).get("uddg", [""])[0]\n        if target:\n            return unquote(target)\n    return href\n\n\nclass DuckDuckGoPublicSearch:\n    """Zero-cost public web search helper.\n\n    This intentionally uses only public search results and never logs in to Facebook,\n    bypasses access controls, or accesses closed/private groups. It is best-effort:\n    search engines and Facebook indexing can change without notice.\n    """\n\n    endpoint = "https://html.duckduckgo.com/html/"\n\n    def __init__(self) -> None:\n        self.client = httpx.Client(\n            timeout=settings.discovery_timeout_seconds,\n            follow_redirects=True,\n            headers={\n                "User-Agent": "MissingPersonHub/0.1 (+public-disaster-information-discovery; admin-reviewed)"\n            },\n        )\n\n    def search(self, query: str, max_results: int | None = None) -> list[SearchResult]:\n        limit = max_results or settings.discovery_results_per_query\n        response = self.client.post(self.endpoint, data={"q": query})\n        response.raise_for_status()\n        soup = BeautifulSoup(response.text, "html.parser")\n        results: list[SearchResult] = []\n        for result in soup.select(".result"):\n            anchor = result.select_one(".result__a")\n            if anchor is None:\n                continue\n            href = _decode_ddg_url(anchor.get("href", ""))\n            if not href.startswith("http"):\n                continue\n            snippet_node = result.select_one(".result__snippet")\n            results.append(\n                SearchResult(\n                    url=canonicalize_url(href),\n                    title=anchor.get_text(" ", strip=True),\n                    snippet=snippet_node.get_text(" ", strip=True) if snippet_node else "",\n                )\n            )\n            if len(results) >= limit:\n                break\n        return results\n\n    def run_queries(self, queries: list[str]) -> list[tuple[str, SearchResult]]:\n        found: list[tuple[str, SearchResult]] = []\n        seen: set[str] = set()\n        for index, query in enumerate(queries[: settings.discovery_max_queries_per_run]):\n            try:\n                for result in self.search(query):\n                    if result.url and result.url not in seen:\n                        seen.add(result.url)\n                        found.append((query, result))\n            except httpx.HTTPError:\n                # Discovery is intentionally fail-soft; manual URL intake remains available.\n                continue\n            if index < len(queries) - 1:\n                time.sleep(settings.discovery_request_delay_seconds)\n        return found\n\n\n\n\nPERSON_LIST_TERMS = [\n    "missing persons list",\n    "missing person list",\n    "missing people list",\n    "list of missing",\n    "names of missing",\n    "missing people names",\n    "missing persons names",\n    "नामावली",\n    "बेपत्ता सूची",\n    "बेपत्ता नाम",\n    "हराएका व्यक्तिको सूची",\n]\n\nMISSING_TERMS = [\n    "missing person",\n    "missing",\n    "has been missing",\n    "missing since",\n    "last seen",\n    "out of contact",\n    "unaccounted for",\n    "बेपत्ता",\n    "हराएको",\n    "हराइरहेको",\n    "सम्पर्कविहीन",\n    "सम्पर्क विहीन",\n]\n\nDIRECT_APPEAL_TERMS = [\n    "please share",\n    "please help find",\n    "help find",\n    "if seen",\n    "contact if",\n    "missing since",\n    "last seen",\n    "has been missing",\n    "खोजिदिनुहोला",\n    "सम्पर्क गर्नुहोला",\n]\n\nPERSON_CONTEXT_TERMS = [\n    "age ",\n    "aged ",\n    "years old",\n    "year old",\n    "contact",\n    "phone",\n    "mobile",\n    "resident of",\n    "last contacted",\n    "last seen",\n    "father",\n    "mother",\n    "son",\n    "daughter",\n    "उमेर",\n    "ठेगाना",\n    "सम्पर्क",\n    "फोन",\n    "मोबाइल",\n    "अन्तिम पटक",\n]\n\nGENERIC_NEWS_TERMS = [\n    "death toll",\n    "hundreds missing",\n    "people remain missing",\n    "hundreds remain missing",\n    "rescue operation",\n    "rescue operations",\n    "live update",\n    "latest update",\n    "flood update",\n    "casualty",\n    "casualties",\n    "bodies recovered",\n    "body recovered",\n    "authorities said",\n    "government said",\n    "breaking news",\n]\n\nGENERIC_NAME_WORDS = {\n    "missing",\n    "person",\n    "people",\n    "please",\n    "share",\n    "flood",\n    "flash",\n    "nepal",\n    "news",\n    "latest",\n    "update",\n    "live",\n    "death",\n    "toll",\n    "rescue",\n    "facebook",\n    "group",\n    "official",\n}\n\n\ndef is_facebook_url(url: str) -> bool:\n    canonical = canonicalize_url(url)\n\n    if not canonical:\n        return False\n\n    host = urlparse(canonical).netloc.casefold()\n\n    return (\n        host == "facebook.com"\n        or host.endswith(".facebook.com")\n        or host == "fb.com"\n        or host.endswith(".fb.com")\n    )\n\n\ndef _has_probable_english_person_name(\n    text: str,\n    disaster: Disaster,\n) -> bool:\n    """Best-effort text signal only.\n\n    This does NOT identify anybody from a photograph.\n    It only detects name-like text already present in the\n    public search result title/snippet.\n    """\n    blocked = set(GENERIC_NAME_WORDS)\n\n    blocked.add(disaster.disaster_type.casefold())\n\n    for location in disaster.locations():\n        for token in location.split():\n            blocked.add(token.casefold())\n\n    for token in disaster.name.split():\n        blocked.add(token.casefold())\n\n    # Two adjacent capitalized words are a useful signal for\n    # English/transliterated personal names such as "Atul Pathak".\n    pattern = re.compile(\n        r"\\b([A-Z][A-Za-z\'-]{2,})\\s+"\n        r"([A-Z][A-Za-z\'-]{2,})\\b"\n    )\n\n    for match in pattern.finditer(text):\n        first = match.group(1).casefold()\n        second = match.group(2).casefold()\n\n        if first in blocked or second in blocked:\n            continue\n\n        return True\n\n    return False\n\n\ndef is_person_specific_candidate(\n    result: SearchResult,\n    disaster: Disaster,\n) -> bool:\n    """Admit only person-level/list-level missing results.\n\n    General disaster news is deliberately rejected from the\n    missing-person review queue.\n    """\n    text = f"{result.title or \'\'} {result.snippet or \'\'}".strip()\n\n    if not text:\n        return False\n\n    folded = text.casefold()\n\n    # A genuine list/name-list is directly useful to this project.\n    if any(term.casefold() in folded for term in PERSON_LIST_TERMS):\n        return True\n\n    has_missing_signal = any(\n        term.casefold() in folded\n        for term in MISSING_TERMS\n    )\n\n    if not has_missing_signal:\n        return False\n\n    has_name = _has_probable_english_person_name(\n        text,\n        disaster,\n    )\n\n    has_direct_appeal = any(\n        term.casefold() in folded\n        for term in DIRECT_APPEAL_TERMS\n    )\n\n    has_person_context = any(\n        term.casefold() in folded\n        for term in PERSON_CONTEXT_TERMS\n    )\n\n    # Nepali notices often expose structured fields rather than\n    # English-style capitalization.\n    has_nepali_structure = (\n        any(\n            term in text\n            for term in [\n                "नाम",\n                "उमेर",\n                "ठेगाना",\n                "सम्पर्क",\n                "फोन",\n            ]\n        )\n        and any(\n            term in text\n            for term in [\n                "बेपत्ता",\n                "हराएको",\n                "सम्पर्कविहीन",\n                "सम्पर्क विहीन",\n            ]\n        )\n    )\n\n    news_hits = sum(\n        1\n        for term in GENERIC_NEWS_TERMS\n        if term.casefold() in folded\n    )\n\n    # General flood coverage should not enter the queue merely\n    # because it contains "hundreds missing".\n    if news_hits >= 1 and not (\n        has_name\n        and (\n            has_direct_appeal\n            or has_person_context\n        )\n    ):\n        return False\n\n    if has_name and (\n        has_direct_appeal\n        or has_person_context\n        or "missing person" in folded\n        or "missing since" in folded\n    ):\n        return True\n\n    if has_nepali_structure:\n        return True\n\n    if has_missing_signal and has_person_context:\n        return True\n\n    return False\n\n\n\nPHONE_RE = re.compile(r"(?<!\\d)(?:\\+?977[-\\s]?)?(?:9\\d[\\d\\s-]{7,12})(?!\\d)")\nAGE_RE = re.compile(\n    r"\\b(?:age[d]?\\s*[:\\-]?\\s*)?(\\d{1,2})\\s*(?:years?\\s*old|year\\s*old|yrs?|y/o)\\b",\n    re.IGNORECASE,\n)\nNAME_RE = re.compile(\n    r"\\b([A-Z][A-Za-z\'-]{2,})\\s+([A-Z][A-Za-z\'-]{2,})\\b"\n)\n\nDIRECT_MISSING_TERMS = [\n    "missing person",\n    "person missing",\n    "has been missing",\n    "is missing",\n    "missing since",\n    "currently missing",\n    "out of contact",\n    "cannot be contacted",\n    "unable to contact",\n    "not in contact",\n    "contact ma aaunu vako xaina",\n    "contact ma aaunu bhako xaina",\n    "contact ma aaunu va ko xaina",\n    "contact ma aaunu vako chaina",\n    "contact ma xaina",\n    "contact ma chaina",\n    "sampark ma xaina",\n    "samparka ma xaina",\n    "बेपत्ता",\n    "हराएको",\n    "हराइरहेको",\n    "हराइरहनु",\n    "सम्पर्कविहीन",\n    "सम्पर्क विहीन",\n]\n\nCONTACT_APPEAL_TERMS = [\n    "please contact",\n    "please share",\n    "please help",\n    "help find",\n    "if you have any information",\n    "if anyone has information",\n    "if seen",\n    "contact:",\n    "contact number",\n    "call",\n    "phone",\n    "mobile",\n    "सम्पर्क गर्नुहोस्",\n    "सम्पर्क गराइदिनुहोस्",\n    "सम्पर्क गर्नुहोला",\n    "खोजिदिनुहोला",\n    "जानकारी भए",\n]\n\nLAST_SEEN_TERMS = [\n    "last seen",\n    "last known location",\n    "missing from",\n    "missing since",\n    "expected to return",\n    "last contacted",\n    "since yesterday",\n    "since today",\n    "अन्तिम पटक",\n    "देखि सम्पर्क",\n]\n\nLIST_TERMS = [\n    "missing persons list",\n    "missing person list",\n    "missing people list",\n    "list of missing",\n    "names of missing",\n    "missing people names",\n    "missing persons names",\n    "नामावली",\n    "बेपत्ता सूची",\n    "बेपत्ता नाम",\n]\n\nFAMILY_TERMS = [\n    "whole family",\n    "family missing",\n    "parents are missing",\n    "parents missing",\n    "mother missing",\n    "father missing",\n    "parents",\n    "family members",\n    "परिवार",\n    "आमा",\n    "बुबा",\n]\n\nGENERIC_NEWS_TERMS = [\n    "death toll",\n    "toll rises",\n    "hundreds missing",\n    "people remain missing",\n    "remain missing after",\n    "rescue operation",\n    "rescue operations",\n    "rescue teams",\n    "latest update",\n    "live update",\n    "breaking news",\n    "flood update",\n    "floodwaters surged",\n    "roads and bridges",\n    "bridge swept away",\n    "bodies recovered",\n    "body recovered",\n    "authorities said",\n    "government said",\n    "casualties",\n]\n\nGENERIC_NAME_WORDS = {\n    "missing",\n    "person",\n    "people",\n    "flood",\n    "floods",\n    "nepal",\n    "rasuwa",\n    "facebook",\n    "official",\n    "news",\n    "latest",\n    "update",\n    "rescue",\n    "family",\n    "group",\n    "support",\n    "welcome",\n    "texas",\n}\n\n\ndef is_facebook_url(url: str) -> bool:\n    canonical = canonicalize_url(url)\n    if not canonical:\n        return False\n\n    host = urlparse(canonical).netloc.casefold()\n\n    return (\n        host == "facebook.com"\n        or host.endswith(".facebook.com")\n        or host == "fb.com"\n        or host.endswith(".fb.com")\n    )\n\n\ndef is_facebook_post_url(url: str) -> bool:\n    """Prefer actual public Facebook content over page/group homepages."""\n    canonical = canonicalize_url(url)\n\n    if not canonical or not is_facebook_url(canonical):\n        return False\n\n    parsed = urlparse(canonical)\n    path = parsed.path.casefold()\n\n    if "/posts/" in path:\n        return True\n\n    if path.startswith("/groups/") and "/posts/" in path:\n        return True\n\n    if "permalink.php" in path:\n        return True\n\n    if "story.php" in path:\n        return True\n\n    if "/reel/" in path or "/reels/" in path:\n        return True\n\n    if "/photo" in path or "/photos/" in path:\n        return True\n\n    if "/share/p/" in path or "/share/v/" in path:\n        return True\n\n    return False\n\n\ndef _contains(text: str, terms: list[str]) -> bool:\n    folded = text.casefold()\n    return any(term.casefold() in folded for term in terms)\n\n\ndef _has_probable_name(text: str, disaster: Disaster) -> bool:\n    blocked = set(GENERIC_NAME_WORDS)\n\n    for token in disaster.name.split():\n        blocked.add(token.casefold())\n\n    for location in disaster.locations():\n        for token in location.split():\n            blocked.add(token.casefold())\n\n    for match in NAME_RE.finditer(text):\n        first = match.group(1).casefold()\n        second = match.group(2).casefold()\n\n        if first in blocked or second in blocked:\n            continue\n\n        return True\n\n    return False\n\n\ndef _has_event_context(text: str, disaster: Disaster) -> bool:\n    folded = text.casefold()\n\n    event_terms = [\n        disaster.name,\n        disaster.disaster_type,\n        "Nepal",\n        "Nepali",\n        "Kathmandu",\n    ]\n\n    event_terms.extend(disaster.locations())\n\n    # Avoid accepting an unrelated foreign result just because\n    # the search query itself mentioned Rasuwa.\n    return any(\n        term and term.casefold() in folded\n        for term in event_terms\n    )\n\n\ndef facebook_person_notice_score(\n    result: SearchResult,\n    disaster: Disaster,\n) -> tuple[int, list[str]]:\n    """Score only text already present in the public search result.\n\n    Photos are never used to identify a person.\n    """\n    text = f"{result.title or \'\'} {result.snippet or \'\'}".strip()\n\n    if not text:\n        return 0, ["empty"]\n\n    score = 0\n    reasons: list[str] = []\n\n    if _contains(text, DIRECT_MISSING_TERMS):\n        score += 4\n        reasons.append("direct-missing-language")\n\n    if _contains(text, LIST_TERMS):\n        score += 6\n        reasons.append("missing-person-list")\n\n    if PHONE_RE.search(text):\n        score += 4\n        reasons.append("contact-number")\n\n    if AGE_RE.search(text):\n        score += 2\n        reasons.append("age")\n\n    if _contains(text, CONTACT_APPEAL_TERMS):\n        score += 2\n        reasons.append("contact-appeal")\n\n    if _contains(text, LAST_SEEN_TERMS):\n        score += 2\n        reasons.append("last-seen-or-since")\n\n    if _contains(text, FAMILY_TERMS):\n        score += 2\n        reasons.append("family-specific")\n\n    if _has_probable_name(text, disaster):\n        score += 3\n        reasons.append("name-like-text")\n\n    news_hits = sum(\n        1\n        for term in GENERIC_NEWS_TERMS\n        if term.casefold() in text.casefold()\n    )\n\n    if news_hits:\n        score -= 5 * news_hits\n        reasons.append(f"generic-news-{news_hits}")\n\n    return score, reasons\n\n\ndef is_person_specific_candidate(\n    result: SearchResult,\n    disaster: Disaster,\n    *,\n    require_event_context: bool = True,\n) -> bool:\n    if not is_facebook_post_url(result.url):\n        return False\n\n    text = f"{result.title or \'\'} {result.snippet or \'\'}".strip()\n\n    if require_event_context and not _has_event_context(\n        text,\n        disaster,\n    ):\n        return False\n\n    score, _ = facebook_person_notice_score(\n        result,\n        disaster,\n    )\n\n    # Require person-level evidence, not merely the word "missing".\n    has_structured_person_evidence = (\n        PHONE_RE.search(text) is not None\n        or AGE_RE.search(text) is not None\n        or _contains(text, CONTACT_APPEAL_TERMS)\n        or _contains(text, LAST_SEEN_TERMS)\n        or _contains(text, LIST_TERMS)\n        or _has_probable_name(text, disaster)\n        or _contains(text, FAMILY_TERMS)\n    )\n\n    return score >= 6 and has_structured_person_evidence\n\n\nFACEBOOK_SOURCE_SWEEP_MAX_SOURCES = 4\nFACEBOOK_SOURCE_SWEEP_QUERIES_PER_SOURCE = 4\n\n\ndef facebook_source_scope(url: str) -> str | None:\n    """Return the public Facebook page/group scope for a post URL.\n\n    Examples:\n      facebook.com/memenepalofficial/posts/123\n          -> memenepalofficial\n\n      facebook.com/groups/rasuwa/posts/456\n          -> groups/rasuwa\n    """\n    canonical = canonicalize_url(url)\n    if not canonical:\n        return None\n\n    parsed = urlparse(canonical)\n    host = parsed.netloc.casefold()\n\n    if not (\n        host == "facebook.com"\n        or host.endswith(".facebook.com")\n        or host == "fb.com"\n        or host.endswith(".fb.com")\n    ):\n        return None\n\n    parts = [\n        unquote(part).strip()\n        for part in parsed.path.split("/")\n        if part.strip()\n    ]\n\n    if not parts:\n        return None\n\n    first = parts[0].casefold()\n\n    if first == "groups" and len(parts) >= 2:\n        return f"groups/{parts[1]}"\n\n    # These URL shapes do not reliably tell us which page/group owns the post.\n    unsupported_roots = {\n        "watch",\n        "reel",\n        "reels",\n        "share",\n        "photo",\n        "photos",\n        "story.php",\n        "permalink.php",\n        "plugins",\n    }\n\n    if first in unsupported_roots:\n        return None\n\n    return parts[0]\n\n\ndef generate_facebook_source_queries(\n    disaster: Disaster,\n    source_scope: str,\n    max_queries: int = FACEBOOK_SOURCE_SWEEP_QUERIES_PER_SOURCE,\n) -> list[str]:\n    """Search the same public Facebook page/group for more\n    person-level missing notices.\n    """\n    locations = disaster.locations() or [disaster.name]\n    site = f"site:facebook.com/{source_scope}"\n\n    templates = [\n        "{site} {location} out of contact",\n        "{site} {location} last seen",\n        "{site} {location} missing persons list",\n        "{site} {location} missing people names",\n        "{site} {location} बेपत्ता नामावली",\n        "{site} {location} सम्पर्कविहीन नाम",\n    ]\n\n    queries: list[str] = []\n    seen: set[str] = set()\n\n    for template in templates:\n        for location in locations:\n            query = template.format(\n                site=site,\n                source=source_scope,\n                location=location,\n            ).strip()\n\n            if query in seen:\n                continue\n\n            seen.add(query)\n            queries.append(query)\n\n            if len(queries) >= max_queries:\n                return queries\n\n    return queries\n\ndef expand_facebook_sources(\n    provider,\n    disaster: Disaster,\n    seed_results: list[tuple[str, SearchResult]],\n) -> list[tuple[str, SearchResult]]:\n    """Sweep a few publicly indexed posts from promising Facebook sources."""\n    scopes: list[str] = []\n    seen_scopes: set[str] = set()\n\n    for _, result in seed_results:\n        scope = facebook_source_scope(result.url)\n\n        if not scope or scope in seen_scopes:\n            continue\n\n        seen_scopes.add(scope)\n        scopes.append(scope)\n\n        if len(scopes) >= FACEBOOK_SOURCE_SWEEP_MAX_SOURCES:\n            break\n\n    expanded: list[tuple[str, SearchResult]] = []\n\n    for scope in scopes:\n        queries = generate_facebook_source_queries(\n            disaster,\n            scope,\n            max_queries=FACEBOOK_SOURCE_SWEEP_QUERIES_PER_SOURCE,\n        )\n\n        expanded.extend(provider.run_queries(queries))\n\n    return expanded\n\ndef discover_candidates(\n    db: Session,\n    disaster: Disaster,\n    platform: str = "facebook",\n    provider: DuckDuckGoPublicSearch | None = None,\n) -> int:\n    """Discover missing-person posts, not general disaster news."""\n    provider = provider or DuckDuckGoPublicSearch()\n\n    primary_queries = generate_queries(\n        disaster,\n        platform=platform,\n    )\n\n    primary_results = provider.run_queries(\n        primary_queries\n    )\n\n    if platform == "facebook":\n        # First-stage results must be real person-level posts\n        # AND explicitly connected to the selected disaster/event.\n        qualified_primary = [\n            (query, result)\n            for query, result in primary_results\n            if is_person_specific_candidate(\n                result,\n                disaster,\n                require_event_context=True,\n            )\n        ]\n\n        # Only a valid missing-person post is allowed to promote\n        # its page/group into a source sweep.\n        expanded_results = expand_facebook_sources(\n            provider,\n            disaster,\n            qualified_primary,\n        )\n\n        # Source-sweep results can omit the event name/location\n        # because the source was discovered from a valid event post.\n        qualified_expanded = [\n            (query, result)\n            for query, result in expanded_results\n            if is_person_specific_candidate(\n                result,\n                disaster,\n                require_event_context=True,\n            )\n        ]\n\n        all_results = (\n            qualified_primary\n            + qualified_expanded\n        )\n\n    else:\n        all_results = list(primary_results)\n\n    deduped: list[tuple[str, SearchResult]] = []\n    seen_urls: set[str] = set()\n\n    for query, result in all_results:\n        canonical = canonicalize_url(result.url)\n\n        if not canonical:\n            continue\n\n        if canonical in seen_urls:\n            continue\n\n        seen_urls.add(canonical)\n\n        deduped.append(\n            (\n                query,\n                SearchResult(\n                    url=canonical,\n                    title=result.title,\n                    snippet=result.snippet,\n                ),\n            )\n        )\n\n    added = 0\n\n    for query, result in deduped:\n        if platform == "facebook":\n            if not is_facebook_post_url(result.url):\n                continue\n\n        elif platform == "x":\n            if "x.com" not in result.url:\n                continue\n\n        elif platform != "web":\n            if f"{platform}.com" not in result.url:\n                continue\n\n        exists = db.scalar(\n            select(DiscoveryCandidate.id).where(\n                DiscoveryCandidate.disaster_id\n                == disaster.id,\n                DiscoveryCandidate.url\n                == result.url,\n            )\n        )\n\n        if exists:\n            continue\n\n        db.add(\n            DiscoveryCandidate(\n                disaster_id=disaster.id,\n                platform=platform,\n                query=query,\n                url=result.url,\n                title=result.title,\n                snippet=result.snippet,\n            )\n        )\n\n        added += 1\n\n    return added\n\n', 'app/templates/admin_discovery.html': '{% extends "base.html" %}\n{% block content %}\n\n<h1>Public Social Discovery</h1>\n\n<p class="muted">\n  V0 searches public web indexes only. It never logs into Facebook or accesses\n  closed/private groups. Every result remains subject to admin review.\n</p>\n\n<form method="get" class="card inline">\n  <div>\n    <label>Event</label>\n    <select name="disaster_id">\n      {% for d in disasters %}\n      <option value="{{ d.id }}" {% if selected and selected.id == d.id %}selected{% endif %}>\n        {{ d.name }}\n      </option>\n      {% endfor %}\n    </select>\n  </div>\n\n  <div>\n    <label>Platform</label>\n    <select name="platform">\n      {% for p in [\'facebook\',\'web\',\'instagram\',\'tiktok\',\'x\',\'reddit\'] %}\n      <option value="{{ p }}" {% if platform == p %}selected{% endif %}>{{ p }}</option>\n      {% endfor %}\n    </select>\n  </div>\n\n  <input type="hidden" name="view" value="{{ view }}">\n\n  <div>\n    <button>Load Discovery</button>\n  </div>\n</form>\n\n{% if selected %}\n\n{% if wide_error %}\n<div class="notice">\n  <strong>Wide Discovery could not run.</strong><br>\n  The configured Serper / Google Search provider is unavailable, rejected, or\n  has reached its quota.\n</div>\n{% endif %}\n\n{% if wide_stats %}\n<div class="notice">\n  <strong>Wide Discovery finished</strong><br>\n  Queries searched: {{ wide_stats.queries }}<br>\n  Raw search results: {{ wide_stats.raw }}<br>\n  New candidates sent to review: {{ wide_stats.added }}\n</div>\n{% endif %}\n\n<div class="card">\n  <h2>Findings queue</h2>\n  <p class="muted">\n    Relevant and irrelevant decisions are retained. Nothing is deleted, so an\n    administrator can restore a result later if it was classified incorrectly.\n  </p>\n\n  <div class="inline" style="gap:8px; flex-wrap:wrap">\n    <a href="{{ queue_links.review }}">To Review ({{ queue_counts.review }})</a>\n    <a href="{{ queue_links.relevant }}">Relevant ({{ queue_counts.relevant }})</a>\n    <a href="{{ queue_links.irrelevant }}">Irrelevant ({{ queue_counts.irrelevant }})</a>\n    <a href="{{ queue_links.processed }}">Processed ({{ queue_counts.processed }})</a>\n  </div>\n</div>\n\n<form method="get" class="card inline">\n  <input type="hidden" name="disaster_id" value="{{ selected.id }}">\n  <input type="hidden" name="platform" value="{{ platform }}">\n  <input type="hidden" name="view" value="{{ view }}">\n\n  <div style="min-width:320px; flex:1">\n    <label>Search findings by person name</label>\n    <input\n      name="q"\n      value="{{ q }}"\n      placeholder="Name in English or Nepali"\n      autocomplete="off"\n    >\n  </div>\n\n  <div>\n    <button>Search Findings</button>\n  </div>\n\n  {% if q %}\n  <div>\n    <a href="{{ clear_search_url }}">Clear search</a>\n  </div>\n  {% endif %}\n</form>\n\n<div class="grid">\n  <div class="card">\n    <h2>Automated Discovery</h2>\n    <p>Runs the bounded public-web discovery collector and person-level filters.</p>\n    <form method="post" action="/admin/discovery/run">\n      <input type="hidden" name="disaster_id" value="{{ selected.id }}">\n      <input type="hidden" name="platform" value="{{ platform }}">\n      <button>Run Discovery Bot</button>\n    </form>\n  </div>\n\n  {% if platform == \'facebook\' %}\n  <div class="card">\n    <h2>Wide Discovery</h2>\n    <p>\n      Person-focused Facebook discovery using affected places, stronger\n      missing-person phrases, the event date window, and human-confirmed\n      productive sources.\n    </p>\n\n    <p>\n      <strong>Provider:</strong> {{ wide_provider_status.name }} —\n      {% if wide_provider_status.available %}\n        <span class="badge">READY</span>\n      {% else %}\n        <span class="badge">NOT CONFIGURED</span>\n      {% endif %}\n    </p>\n\n    <p class="muted">{{ wide_provider_status.detail }}</p>\n\n    {% if wide_provider_status.available %}\n    <form method="post" action="/admin/wide-discovery/run">\n      <input type="hidden" name="disaster_id" value="{{ selected.id }}">\n      <button>Run Wide Discovery</button>\n    </form>\n    {% else %}\n    <button disabled>Run Wide Discovery</button>\n    <p class="muted">Set SERPER_API_KEY in the server environment to enable it.</p>\n    {% endif %}\n\n    <p class="muted">\n      A run uses at most 40 search queries. Avoid repeating it unnecessarily.\n    </p>\n\n    <details style="margin-top:12px">\n      <summary>Show Wide Search Plan ({{ wide_query_plan|length }} queries)</summary>\n      <div style="max-height:420px; overflow:auto; margin-top:10px">\n        {% for query in wide_query_plan %}\n        <p><strong>{{ \'%03d\'|format(loop.index) }}.</strong> <code>{{ query }}</code></p>\n        {% else %}\n        <p>No wide queries generated.</p>\n        {% endfor %}\n      </div>\n    </details>\n  </div>\n  {% endif %}\n\n  <div class="card">\n    <h2>Free AI Review</h2>\n    <p>\n      Review collected candidates using a free interactive AI session. No AI\n      API call is made.\n    </p>\n    <form method="get" action="/admin/ai-review">\n      <input type="hidden" name="disaster_id" value="{{ selected.id }}">\n      <input type="hidden" name="platform" value="{{ platform }}">\n      <button>Prepare Free AI Review</button>\n    </form>\n  </div>\n\n  <div class="card">\n    <h2>Manual URL Intake</h2>\n    <form method="post" action="/admin/discovery/manual">\n      <input type="hidden" name="disaster_id" value="{{ selected.id }}">\n      <input type="hidden" name="platform" value="{{ platform }}">\n      <label>Public source URL</label>\n      <input type="url" name="url" required>\n      <label>Title</label>\n      <input name="title">\n      <label>Snippet/note</label>\n      <textarea name="snippet"></textarea>\n      <button>Add Candidate</button>\n    </form>\n  </div>\n</div>\n\n<details style="margin-top:18px">\n  <summary>Targeted manual searches</summary>\n  <div class="card">\n    {% for query, url in queries %}\n    <p>\n      <a href="{{ url }}" target="_blank" rel="noopener noreferrer">Search</a>\n      — <code>{{ query }}</code>\n    </p>\n    {% else %}\n    <p>No queries.</p>\n    {% endfor %}\n  </div>\n</details>\n\n<h2>\n  {% if view == \'review\' %}To Review{% elif view == \'relevant\' %}Relevant Findings{% elif view == \'irrelevant\' %}Irrelevant Archive{% else %}Processed Findings{% endif %}\n</h2>\n\n<table>\n  <thead>\n    <tr>\n      <th>Platform</th>\n      <th>Candidate</th>\n      <th>Status</th>\n      <th>Review</th>\n      <th>Classification</th>\n    </tr>\n  </thead>\n  <tbody>\n    {% for c in candidates %}\n    <tr>\n      <td>{{ c.platform }}</td>\n      <td>\n        <a href="{{ c.url }}" target="_blank" rel="noopener noreferrer">\n          {{ c.title or c.url }}\n        </a>\n        <br>\n        <span class="muted">{{ c.snippet or \'\' }}</span>\n      </td>\n      <td>{{ c.status }}</td>\n      <td><a href="/admin/discovery/{{ c.id }}">Review Details</a></td>\n      <td>\n        {% if c.status in [\'new\', \'needs_ai\'] %}\n        <form method="post" action="/admin/discovery/{{ c.id }}/status" style="display:inline">\n          <input type="hidden" name="status_action" value="relevant">\n          <input type="hidden" name="platform" value="{{ platform }}">\n          <input type="hidden" name="view" value="{{ view }}">\n          <input type="hidden" name="q" value="{{ q }}">\n          <button>✓ Relevant</button>\n        </form>\n        <form method="post" action="/admin/discovery/{{ c.id }}/status" style="display:inline">\n          <input type="hidden" name="status_action" value="irrelevant">\n          <input type="hidden" name="platform" value="{{ platform }}">\n          <input type="hidden" name="view" value="{{ view }}">\n          <input type="hidden" name="q" value="{{ q }}">\n          <button class="secondary">Not relevant</button>\n        </form>\n        {% elif c.status == \'relevant\' %}\n        <form method="post" action="/admin/discovery/{{ c.id }}/status" style="display:inline">\n          <input type="hidden" name="status_action" value="irrelevant">\n          <input type="hidden" name="platform" value="{{ platform }}">\n          <input type="hidden" name="view" value="{{ view }}">\n          <input type="hidden" name="q" value="{{ q }}">\n          <button class="secondary">Move to Irrelevant</button>\n        </form>\n        {% elif c.status in [\'irrelevant\', \'rejected\'] %}\n        <form method="post" action="/admin/discovery/{{ c.id }}/status" style="display:inline">\n          <input type="hidden" name="status_action" value="restore">\n          <input type="hidden" name="platform" value="{{ platform }}">\n          <input type="hidden" name="view" value="{{ view }}">\n          <input type="hidden" name="q" value="{{ q }}">\n          <button>Restore to Review</button>\n        </form>\n        {% else %}\n        <span class="muted">Already processed</span>\n        {% endif %}\n      </td>\n    </tr>\n    {% else %}\n    <tr>\n      <td colspan="5">No findings in this section.</td>\n    </tr>\n    {% endfor %}\n  </tbody>\n</table>\n\n{% endif %}\n{% endblock %}\n', 'app/templates/admin_discovery_review.html': '{% extends "base.html" %}\n{% block content %}\n\n<h1>Review Discovery Candidate</h1>\n\n<div class="card">\n  <p>\n    <span class="badge">{{ candidate.platform }}</span>\n    <span class="badge">{{ candidate.status }}</span>\n    <a href="{{ candidate.url }}" target="_blank" rel="noopener noreferrer">\n      Open original public post\n    </a>\n  </p>\n\n  <h2>{{ candidate.title or \'Untitled result\' }}</h2>\n  <pre class="wrap">{{ candidate.snippet or \'\' }}</pre>\n\n  {% if candidate.status in [\'new\', \'needs_ai\'] %}\n  <div class="inline" style="margin-top:12px">\n    <form method="post" action="/admin/discovery/{{ candidate.id }}/status">\n      <input type="hidden" name="status_action" value="relevant">\n      <input type="hidden" name="platform" value="{{ candidate.platform }}">\n      <input type="hidden" name="view" value="review">\n      <button>✓ Mark Relevant</button>\n    </form>\n    <form method="post" action="/admin/discovery/{{ candidate.id }}/status">\n      <input type="hidden" name="status_action" value="irrelevant">\n      <input type="hidden" name="platform" value="{{ candidate.platform }}">\n      <input type="hidden" name="view" value="review">\n      <button class="secondary">Mark Irrelevant</button>\n    </form>\n  </div>\n  {% elif candidate.status in [\'irrelevant\', \'rejected\'] %}\n  <form method="post" action="/admin/discovery/{{ candidate.id }}/status">\n    <input type="hidden" name="status_action" value="restore">\n    <input type="hidden" name="platform" value="{{ candidate.platform }}">\n    <input type="hidden" name="view" value="irrelevant">\n    <button>Restore to Review</button>\n  </form>\n  {% endif %}\n</div>\n\n{% if source_image_url %}\n<div class="card">\n  <h2>Picture found in public source</h2>\n  <img\n    src="{{ source_image_url }}"\n    alt="Image attached to the public missing-person post"\n    style="max-width:520px; max-height:520px; object-fit:contain; border-radius:8px"\n  >\n  <p class="muted">\n    Source evidence only. OCR may read written text from this image, but the\n    system does not identify a person from their face or infer identity from appearance.\n  </p>\n</div>\n{% endif %}\n\n{% if ocr_text or ocr_detail %}\n<div class="card">\n  <h2>Text detected in source image</h2>\n  {% if ocr_detail %}<p class="muted">{{ ocr_detail }}</p>{% endif %}\n  {% if ocr_text %}\n  <pre class="wrap">{{ ocr_text }}</pre>\n  {% else %}\n  <p>No OCR text was detected.</p>\n  {% endif %}\n</div>\n{% endif %}\n\n<form\n  method="post"\n  action="/admin/discovery/{{ candidate.id }}/submission"\n  class="card"\n>\n  <h2>Bot-extracted missing-person details</h2>\n  <p class="muted">\n    Title, snippet and any detected poster text are used only as source evidence.\n    Review and correct every field before creating the pending record.\n  </p>\n\n  {% if ocr_text %}\n  <textarea name="ocr_text" style="display:none">{{ ocr_text }}</textarea>\n  {% endif %}\n\n  <div class="inline">\n    <div>\n      <label>Name *</label>\n      <input name="name" value="{{ prefill.name or \'\' }}" required>\n    </div>\n    <div>\n      <label>Nepali name</label>\n      <input name="name_ne" value="{{ prefill.name_ne or \'\' }}">\n    </div>\n    <div>\n      <label>Age</label>\n      <input type="number" name="age" value="{{ prefill.age or \'\' }}">\n    </div>\n  </div>\n\n  <div class="inline">\n    <div>\n      <label>Gender</label>\n      <select name="gender">\n        <option value="" {% if not prefill.gender %}selected{% endif %}>Unknown</option>\n        <option value="Male" {% if prefill.gender == \'Male\' %}selected{% endif %}>Male</option>\n        <option value="Female" {% if prefill.gender == \'Female\' %}selected{% endif %}>Female</option>\n      </select>\n    </div>\n    <div>\n      <label>Last-seen date</label>\n      <input type="date" name="last_seen_date" value="{{ prefill.last_seen_date or \'\' }}">\n    </div>\n    <div>\n      <label>Last-seen time</label>\n      <input type="time" name="last_seen_time" value="{{ prefill.last_seen_time or \'\' }}">\n    </div>\n  </div>\n\n  <label>Last-seen / affected location *</label>\n  <input name="last_seen_location" value="{{ prefill.last_seen_location or \'\' }}" required>\n\n  <label>Clothing</label>\n  <textarea name="clothing">{{ prefill.clothing or \'\' }}</textarea>\n\n  <label>Identification / source details</label>\n  <textarea name="identification_details" rows="8">{{ prefill.identification_details or \'\' }}</textarea>\n\n  <label>Public information contact</label>\n  <input name="public_contact_number" value="{{ prefill.public_contact_number or \'\' }}">\n\n  {% if source_image_url %}\n  <input type="hidden" name="source_image_url" value="{{ source_image_url }}">\n  <p>\n    <label>\n      <input type="checkbox" name="include_source_image" value="1" checked>\n      Include this reviewed source image in the pending missing-person record\n    </label>\n  </p>\n  {% endif %}\n\n  {% if candidate.status not in [\'irrelevant\', \'rejected\'] %}\n  <button>\n    {% if candidate.status == \'reviewed\' %}\n      Create Another Pending Submission From This Source\n    {% else %}\n      Create Prefilled Pending Submission\n    {% endif %}\n  </button>\n  {% else %}\n  <p class="muted">Restore this candidate to review before creating a submission.</p>\n  {% endif %}\n</form>\n\n<p class="muted">\n  The system reads only public text and written text detected in source images.\n  It does not use facial recognition or infer identity from appearance.\n</p>\n\n{% endblock %}\n', 'app/templates/admin_submissions.html': '{% extends "base.html" %}\n{% block content %}\n\n<h1>Pending Submissions</h1>\n\n<p class="muted">\n  AI-extracted information is pre-filled here for human review.\n  Correct anything that is wrong, save the reviewed details,\n  then create or attach the Master record.\n</p>\n\n{% for s in submissions %}\n\n<div class="card">\n\n  <h2>\n    SUB-{{ \'%06d\'|format(s.id) }}\n    — {{ s.kind }}\n  </h2>\n\n  {% if s.photo_path %}\n  <div style="margin-bottom:16px">\n    <p>\n      <strong>Proposed source image</strong>\n    </p>\n\n    <img\n      src="/admin/media/{{ s.photo_path }}"\n      alt="Source image attached to missing-person report"\n      style="\n        max-width:320px;\n        max-height:320px;\n        object-fit:contain;\n        border-radius:8px;\n      "\n    >\n\n    <p class="muted">\n      Source evidence only.\n      Do not use the photograph itself as identity proof.\n    </p>\n  </div>\n  {% endif %}\n\n  {% if s.social_url %}\n  <p>\n    <a\n      href="{{ s.social_url }}"\n      target="_blank"\n      rel="noopener noreferrer"\n    >\n      Open original public source\n    </a>\n  </p>\n  {% endif %}\n\n  {% if s.notes %}\n  <details>\n    <summary>Source / AI review notes</summary>\n    <pre class="wrap">{{ s.notes }}</pre>\n  </details>\n  {% endif %}\n\n  <form\n    method="post"\n    action="/admin/submissions/{{ s.id }}/edit"\n    enctype="multipart/form-data"\n    style="margin-top:16px"\n  >\n\n    <h3>Review extracted information</h3>\n\n    <div class="inline">\n\n      <div>\n        <label>Name</label>\n        <input\n          name="name"\n          value="{{ s.name or \'\' }}"\n          {% if s.kind == \'missing_report\' %}required{% endif %}\n        >\n      </div>\n\n      <div>\n        <label>Nepali name</label>\n        <input\n          name="name_ne"\n          value="{{ s.name_ne or \'\' }}"\n        >\n      </div>\n\n      <div>\n        <label>Age</label>\n        <input\n          type="number"\n          name="age"\n          value="{{ s.age or \'\' }}"\n        >\n      </div>\n\n    </div>\n\n    <div class="inline">\n\n      <div>\n        <label>Gender</label>\n        <select name="gender">\n          <option value="" {% if not s.gender %}selected{% endif %}>Unknown</option>\n          <option value="Male" {% if s.gender == \'Male\' %}selected{% endif %}>Male</option>\n          <option value="Female" {% if s.gender == \'Female\' %}selected{% endif %}>Female</option>\n        </select>\n      </div>\n\n      <div>\n        <label>Last-seen date</label>\n        <input\n          type="date"\n          name="last_seen_date"\n          value="{{ s.last_seen_date.isoformat() if s.last_seen_date else \'\' }}"\n        >\n      </div>\n\n      <div>\n        <label>Last-seen time</label>\n        <input\n          type="time"\n          name="last_seen_time"\n          value="{{ s.last_seen_time.strftime(\'%H:%M\') if s.last_seen_time else \'\' }}"\n        >\n      </div>\n\n    </div>\n\n    <label>Last-seen / affected location</label>\n    <input\n      name="last_seen_location"\n      value="{{ s.last_seen_location or \'\' }}"\n    >\n\n    <label>Clothing</label>\n    <textarea\n      name="clothing"\n    >{{ s.clothing or \'\' }}</textarea>\n\n    <label>Identification details</label>\n    <textarea\n      name="identification_details"\n    >{{ s.identification_details or \'\' }}</textarea>\n\n    <label>Public information contact</label>\n    <input\n      name="public_contact_number"\n      value="{{ s.public_contact_number or \'\' }}"\n    >\n\n    <label>\n      Replace / add source image\n    </label>\n\n    <input\n      type="file"\n      name="photo"\n      accept="image/jpeg,image/png,image/webp"\n    >\n\n    <p class="muted">\n      If the AI could not retrieve the public post image,\n      an administrator may upload the source image here.\n    </p>\n\n    <button>\n      Save Reviewed Details\n    </button>\n\n  </form>\n\n\n  {% if s.kind == \'missing_report\' %}\n\n  <p>\n    <strong>Affected-area match:</strong>\n\n    {% if location_match_map.get(s.id) %}\n    <span class="badge">YES</span>\n    {% else %}\n    <span class="badge">NO / REVIEW</span>\n    {% endif %}\n  </p>\n\n  {% endif %}\n\n\n  {% if duplicate_map.get(s.id) %}\n\n  <div class="notice">\n\n    <strong>\n      Possible duplicates\n    </strong>\n\n    {% for p, score in duplicate_map[s.id] %}\n\n    <div>\n      {{ score }}%\n      — {{ p.case_number }}\n      — {{ p.name }}\n      — {{ p.last_seen_location }}\n    </div>\n\n    {% endfor %}\n\n  </div>\n\n  {% endif %}\n\n\n  {% if s.kind == \'missing_report\' %}\n\n  <form\n    method="post"\n    action="/admin/submissions/{{ s.id }}/approve-new"\n    style="display:inline"\n  >\n    <button>\n      Approve & Create New Master\n    </button>\n  </form>\n\n  {% endif %}\n\n\n  <form\n    method="post"\n    action="/admin/submissions/{{ s.id }}/attach"\n    class="inline"\n    style="margin-top:8px"\n  >\n\n    <div>\n      <select\n        name="person_id"\n        required\n      >\n\n        <option value="">\n          Attach to existing Master...\n        </option>\n\n        {% for p in people_by_disaster.get(s.disaster_id, []) %}\n\n        <option value="{{ p.id }}">\n          {{ p.case_number }}\n          — {{ p.name }}\n        </option>\n\n        {% endfor %}\n\n      </select>\n    </div>\n\n    <div>\n      <button class="secondary">\n        Approve & Attach\n      </button>\n    </div>\n\n  </form>\n\n\n  <form\n    method="post"\n    action="/admin/submissions/{{ s.id }}/reject"\n    style="\n      display:inline;\n      margin-top:8px;\n    "\n  >\n    <button class="danger">\n      Reject\n    </button>\n  </form>\n\n</div>\n\n{% else %}\n\n<div class="card">\n  No pending submissions.\n</div>\n\n{% endfor %}\n\n{% endblock %}\n', 'app/services/source_ocr.py': 'from __future__ import annotations\n\nimport os\nimport shutil\nimport subprocess\nimport tempfile\nfrom dataclasses import dataclass\nfrom functools import lru_cache\nfrom pathlib import Path\n\nfrom PIL import Image, ImageEnhance, ImageFilter, ImageOps, UnidentifiedImageError\n\n\n@dataclass(slots=True)\nclass OCRResult:\n    text: str\n    available: bool\n    languages: str\n    detail: str\n\n\ndef _tesseract_command() -> str | None:\n    configured = os.getenv("TESSERACT_CMD", "").strip()\n    if configured and Path(configured).is_file():\n        return configured\n\n    found = shutil.which("tesseract")\n    if found:\n        return found\n\n    if os.name == "nt":\n        for candidate in (\n            r"C:\\Program Files\\Tesseract-OCR\\tesseract.exe",\n            r"C:\\Program Files (x86)\\Tesseract-OCR\\tesseract.exe",\n        ):\n            if Path(candidate).is_file():\n                return candidate\n\n    return None\n\n\n@lru_cache(maxsize=4)\ndef _available_languages(command: str) -> tuple[str, ...]:\n    try:\n        completed = subprocess.run(\n            [command, "--list-langs"],\n            capture_output=True,\n            text=True,\n            encoding="utf-8",\n            errors="replace",\n            timeout=15,\n            check=False,\n        )\n    except (OSError, subprocess.SubprocessError):\n        return ()\n\n    if completed.returncode != 0:\n        return ()\n\n    languages = []\n    for line in completed.stdout.splitlines():\n        value = line.strip()\n        if value and not value.lower().startswith("list of available"):\n            languages.append(value)\n    return tuple(languages)\n\n\ndef _selected_languages(command: str) -> str:\n    available = set(_available_languages(command))\n    configured = [\n        item.strip()\n        for item in os.getenv("TESSERACT_LANGS", "eng+nep").split("+")\n        if item.strip()\n    ]\n    selected = [item for item in configured if item in available]\n\n    if not selected and "eng" in available:\n        selected = ["eng"]\n    if not selected and available:\n        selected = [sorted(available)[0]]\n\n    return "+".join(selected)\n\n\ndef ocr_available() -> bool:\n    command = _tesseract_command()\n    return bool(command and _selected_languages(command))\n\n\ndef _prepare_image(source: Path, destination: Path) -> None:\n    with Image.open(source) as image:\n        image = ImageOps.exif_transpose(image)\n        image = image.convert("L")\n\n        width, height = image.size\n        largest = max(width, height)\n        if largest < 1800:\n            scale = min(3.0, 1800 / max(largest, 1))\n            image = image.resize(\n                (max(1, int(width * scale)), max(1, int(height * scale))),\n                Image.Resampling.LANCZOS,\n            )\n\n        image = ImageOps.autocontrast(image)\n        image = ImageEnhance.Contrast(image).enhance(1.35)\n        image = image.filter(ImageFilter.SHARPEN)\n        image.save(destination, format="PNG")\n\n\ndef _clean_ocr_text(text: str) -> str:\n    lines: list[str] = []\n    seen: set[str] = set()\n\n    for raw_line in text.replace("\\x0c", "").splitlines():\n        line = " ".join(raw_line.split()).strip()\n        if len(line) < 2:\n            continue\n        key = line.casefold()\n        if key in seen:\n            continue\n        seen.add(key)\n        lines.append(line)\n\n    return "\\n".join(lines).strip()\n\n\ndef extract_ocr_text(image_path: str | Path) -> OCRResult:\n    source = Path(image_path)\n    command = _tesseract_command()\n\n    if command is None:\n        return OCRResult(\n            text="",\n            available=False,\n            languages="",\n            detail=(\n                "Tesseract OCR is not installed or not discoverable. "\n                "Set TESSERACT_CMD after installing it."\n            ),\n        )\n\n    languages = _selected_languages(command)\n    if not languages:\n        return OCRResult(\n            text="",\n            available=False,\n            languages="",\n            detail="Tesseract is installed but no usable language data was found.",\n        )\n\n    if not source.is_file():\n        return OCRResult(\n            text="",\n            available=True,\n            languages=languages,\n            detail="OCR source image was not available locally.",\n        )\n\n    outputs: list[str] = []\n\n    try:\n        with tempfile.TemporaryDirectory(prefix="mp-ocr-") as temp_dir:\n            prepared = Path(temp_dir) / "prepared.png"\n            _prepare_image(source, prepared)\n\n            for psm in (6, 11):\n                try:\n                    completed = subprocess.run(\n                        [\n                            command,\n                            str(prepared),\n                            "stdout",\n                            "-l",\n                            languages,\n                            "--oem",\n                            "3",\n                            "--psm",\n                            str(psm),\n                        ],\n                        capture_output=True,\n                        text=True,\n                        encoding="utf-8",\n                        errors="replace",\n                        timeout=35,\n                        check=False,\n                    )\n                except (OSError, subprocess.SubprocessError):\n                    continue\n\n                if completed.returncode == 0 and completed.stdout.strip():\n                    outputs.append(completed.stdout)\n\n    except (OSError, ValueError, UnidentifiedImageError):\n        return OCRResult(\n            text="",\n            available=True,\n            languages=languages,\n            detail="The source image could not be prepared for OCR.",\n        )\n\n    text = _clean_ocr_text("\\n".join(outputs))\n\n    if text:\n        return OCRResult(\n            text=text,\n            available=True,\n            languages=languages,\n            detail=f"OCR completed using: {languages}",\n        )\n\n    return OCRResult(\n        text="",\n        available=True,\n        languages=languages,\n        detail=(\n            "OCR ran but no reliable text was detected. "\n            "The administrator can still inspect the source image manually."\n        ),\n    )\n', 'tests/test_candidate_extract_upgrade.py': 'from datetime import date\n\nfrom app.models import Disaster, DiscoveryCandidate\nfrom app.services.candidate_extract import extract_candidate_prefill\n\n\ndef event():\n    return Disaster(\n        code="RF",\n        name="Rasuwa Flood",\n        disaster_type="flood",\n        start_date=date(2026, 8, 26),\n        affected_locations="Rasuwa\\nTimure\\nBetrawati\\nSyafrubesi\\nMailung",\n    )\n\n\ndef candidate(title, snippet=""):\n    return DiscoveryCandidate(\n        disaster_id=1,\n        platform="facebook",\n        query="test",\n        url="https://facebook.com/example/posts/123",\n        title=title,\n        snippet=snippet,\n    )\n\n\ndef test_rich_text_prefill_extracts_time_location_and_contacts():\n    data = extract_candidate_prefill(\n        candidate(\n            "Person Missing Rajan Shrestha",\n            "Rajan Shrestha, age 41, last seen in Timure, Rasuwa at 8:30 AM. Contact 9841008720.",\n        ),\n        event(),\n    )\n    assert data["name"] == "Rajan Shrestha"\n    assert data["age"] == 41\n    assert data["last_seen_time"] == "08:30"\n    assert data["last_seen_location"] == "Timure, Rasuwa"\n    assert data["public_contact_number"] == "9841008720"\n\n\ndef test_ocr_nepali_poster_can_supply_structured_fields():\n    data = extract_candidate_prefill(\n        candidate("Please share"),\n        event(),\n        ocr_text=(\n            "नाम: सुमन मगर\\n"\n            "उमेर: २१\\n"\n            "लिङ्ग: पुरुष\\n"\n            "हराएको स्थान: टिमुरे\\n"\n            "सम्पर्क: ९८४१००८७२०"\n        ),\n    )\n    assert data["name"] == "सुमन मगर"\n    assert data["name_ne"] == "सुमन मगर"\n    assert data["age"] == 21\n    assert data["gender"] == "Male"\n    assert data["last_seen_location"] == "टिमुरे"\n    assert data["public_contact_number"] == "9841008720"\n\n\ndef test_gender_is_not_inferred_from_name():\n    data = extract_candidate_prefill(candidate("Person Missing Anushka Pandey"), event())\n    assert data["gender"] is None\n', 'tests/test_wide_discovery_precision_upgrade.py': 'from datetime import date\n\nfrom app.models import Disaster\nfrom app.services.wide_discovery import WIDE_MAX_QUERIES, generate_wide_queries\n\n\ndef event():\n    return Disaster(\n        code="RF",\n        name="Rasuwa Flood",\n        disaster_type="flood",\n        start_date=date(2026, 8, 26),\n        affected_locations="Rasuwa\\nTimure\\nBetrawati\\nSyafrubesi\\nMailung",\n    )\n\n\ndef test_wide_plan_is_bounded_and_date_scoped():\n    queries = generate_wide_queries(event(), source_scopes=["Bikkigurungofficial"])\n    assert len(queries) <= WIDE_MAX_QUERIES == 40\n    assert queries\n    assert all("site:facebook.com" in query for query in queries)\n    assert all("after:2026-08-25" in query for query in queries)\n\n\ndef test_wide_plan_avoids_bare_missing_query():\n    queries = generate_wide_queries(event(), source_scopes=[])\n    assert all(\'"missing"\' not in query.casefold() for query in queries)\n    assert any(\'"out of contact"\' in query.casefold() for query in queries)\n    assert any("सम्पर्कविहीन" in query for query in queries)\n', 'tests/test_discovery_queue_upgrade.py': 'from app.database import SessionLocal\nfrom app.models import DiscoveryCandidate\n\n\ndef create_event(client):\n    return client.post(\n        "/admin/events",\n        data={\n            "code": "RF",\n            "name": "Rasuwa Flood",\n            "disaster_type": "flood",\n            "start_date": "2026-08-26",\n            "affected_locations": "Rasuwa\\nTimure",\n            "active": "on",\n        },\n        follow_redirects=False,\n    )\n\n\ndef add_candidate(client, title="Person Missing Rajan Shrestha"):\n    return client.post(\n        "/admin/discovery/manual",\n        data={\n            "disaster_id": "1",\n            "platform": "facebook",\n            "url": "https://facebook.com/example/posts/123",\n            "title": title,\n            "snippet": "Rajan Shrestha age 41 last seen in Timure",\n        },\n        follow_redirects=False,\n    )\n\n\ndef test_irrelevant_archive_and_restore(admin_client):\n    create_event(admin_client)\n    add_candidate(admin_client)\n\n    response = admin_client.post(\n        "/admin/discovery/1/status",\n        data={"status_action": "irrelevant", "platform": "facebook", "view": "review"},\n        follow_redirects=False,\n    )\n    assert response.status_code == 303\n\n    with SessionLocal() as db:\n        assert db.get(DiscoveryCandidate, 1).status == "irrelevant"\n\n    page = admin_client.get("/admin/discovery?disaster_id=1&platform=facebook&view=irrelevant")\n    assert "Rajan Shrestha" in page.text\n    assert "Restore to Review" in page.text\n\n    response = admin_client.post(\n        "/admin/discovery/1/status",\n        data={"status_action": "restore", "platform": "facebook", "view": "irrelevant"},\n        follow_redirects=False,\n    )\n    assert response.status_code == 303\n\n    with SessionLocal() as db:\n        assert db.get(DiscoveryCandidate, 1).status == "needs_ai"\n\n\ndef test_findings_name_search(admin_client):\n    create_event(admin_client)\n    add_candidate(admin_client)\n    page = admin_client.get(\n        "/admin/discovery?disaster_id=1&platform=facebook&view=review&q=Rajan"\n    )\n    assert page.status_code == 200\n    assert "Rajan Shrestha" in page.text\n    page = admin_client.get(\n        "/admin/discovery?disaster_id=1&platform=facebook&view=review&q=NoSuchPerson"\n    )\n    assert "Rajan Shrestha" not in page.text\n'}

NEW_FILES = {'app/services/source_ocr.py', 'tests/test_discovery_queue_upgrade.py', 'tests/test_candidate_extract_upgrade.py', 'tests/test_wide_discovery_precision_upgrade.py'}


def canonical(text: str) -> str:
    return text.replace("\r\n", "\n").replace("\r", "\n")


def digest(text: str) -> str:
    return hashlib.sha256(canonical(text).encode("utf-8")).hexdigest()


def main() -> int:
    missing = []
    changed = []

    for rel, expected in EXPECTED.items():
        path = ROOT / rel
        if not path.is_file():
            missing.append(rel)
            continue
        current = path.read_text(encoding="utf-8")
        if digest(current) != expected:
            changed.append(rel)

    if missing or changed:
        print("ABORTED: local files do not match the files reviewed in ChatGPT.")
        if missing:
            print("Missing:")
            for item in missing:
                print("  -", item)
        if changed:
            print("Changed since upload:")
            for item in changed:
                print("  -", item)
        print("No files were modified.")
        return 2

    for rel in NEW_FILES:
        path = ROOT / rel
        if path.exists():
            print(f"ABORTED: new-file target already exists: {rel}")
            print("No files were modified.")
            return 3

    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup = ROOT / f".discovery-upgrade-backup-{stamp}"

    for rel in EXPECTED:
        source = ROOT / rel
        target = backup / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)

    for rel, content in CONTENTS.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8", newline="\n")
        print("UPDATED:", rel)

    print()
    print("DISCOVERY UPGRADE APPLIED")
    print("Backup:", backup)
    print("Next: run py_compile, focused tests, then the full pytest suite.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
